// Desktop OS – Deel I: Linux – Werkcollege 1
// v = vraag, a = antwoord, o = onderwerp, uitleg = extra uitleg, img/imgAntwoord = afbeelding (map afbeeldingen/)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// oefening: true = blauwe oefenkaart: typ het commando. In a staan commando's na "$ "; regels die met 2 spaties beginnen zijn toetsen of uitvoer.
// De structuur onderaan bepaalt het overzicht rechts.

const kaarten_DOS_linux_wc1 = [
  // ===== Waarom Linux? =====
  { v: "Doel van de werkcolleges (1)", a: "• Vooral het besturingssysteem Linux nader bekijken: een inleiding voor de volgende jaren, en sommige aspecten van besturingssystemen zijn in Linux duidelijker dan in Windows.\n• In Linux kan je rechtstreeks doordringen tot het hart van het systeem.\n• De meeste webservers en mailservers op het internet zijn Linux-servers, door de eenvoud van configuratie en de stabiliteit.\n• Ook in Linux kan je grafisch werken, maar in de werkcolleges duiken we 'achter de vensters'.\n• macOS is net als Linux gebaseerd op Unix: de meeste commando's werken ook in de Mac-terminal.", o: "Waarom Linux?", wit: true,
    uitleg: "Kennis van Linux is volgens de cursus onontbeerlijk voor elke IT'er." },
  { v: "Werken we in de werkcolleges met de grafische omgeving van Linux?", a: "Nee. Ook in Linux kan je grafisch werken, maar in de werkcolleges duiken we 'achter de vensters': enkel de command line.", o: "Waarom Linux?",
    uitleg: "Op servers wordt bijna altijd zonder grafische omgeving gewerkt." },
  { v: "Waarom werken de meeste Linux-commando's ook op een Mac?", a: "Omdat macOS, net als Linux, gebaseerd is op Unix. Je kan ze gebruiken in de Terminal van de Mac.", o: "Waarom Linux?",
    uitleg: "Zie de figuur met de Unix-like stamboom: macOS komt uit de BSD-tak." },
  { v: "Wat is een veel betere manier om de machine vanop afstand te beheren dan de console?", a: "Via het SSH-protocol.", o: "Waarom Linux?",
    uitleg: "SSH = Secure Shell: een versleutelde verbinding naar de commandoregel van een andere computer." },
  { v: "Wat heb je nodig om een machine via SSH te beheren?", a: "Op de machine die je vanop afstand wil beheren moet Open-SSH geïnstalleerd zijn (wat bijna altijd het geval is), en op de computer vanwaar je wil beheren een SSH-client zoals Windows Terminal.", o: "Waarom Linux?",
    uitleg: "Server-kant: Open-SSH (de SSH-server). Client-kant: bv. Windows Terminal, PuTTY of de terminal van Mac/Linux." },
  { v: "Waarom zijn de meeste web- en mailservers op het internet Linux-servers?", a: "Door de eenvoud van configuratie en de stabiliteit van het systeem.", o: "Waarom Linux?" },
  // ===== VM en SSH =====
  { v: "Werken met je Linux-VM en SSH (1)", a: "• Je werkt op individuele Linux virtuele machines (VM's).\n• Aan- en uitzetten met de Virtual Machine Manager (startmenu van de EhB-computers); verbinden met de virtualisatiecluster met je EhB-credentials.\n• Power On, daarna 'Connect or View' → 'connect via console'.\n• In Linux is zowat alles hoofdlettergevoelig: commando's, bestandsnamen, username en paswoord.\n• Beter: de machine vanop afstand beheren via SSH. Op de machine moet Open-SSH staan, op je eigen computer een SSH-client zoals Windows Terminal.\n• Syntax: ssh username@computername -p poort (normaal poort 22).", o: "VM en SSH", wit: true,
    uitleg: "De inloggegevens van je eigen VM staan op Canvas; die staan bewust niet op de kaarten." },
  { v: "Opdracht: verbinden en een bestand overzetten (1). Welke stappen voer je uit?", a: "1. Verbind via SSH met je Linux-machine.\n2. Log in.\n3. Maak in je homedirectory een folder met je voornaam: mkdir voornaam.\n4. Maak ook verbinding via WinSCP.\n5. Maak in Notepad op Windows een tekstbestand.\n6. Kopieer het naar je persoonlijke folder.\n7. Controleer via je SSH-terminal of het bestand is aangekomen.", o: "VM en SSH", oefening: true,
    uitleg: "SSH = een terminal op de Linux-machine, vanop je eigen computer. mkdir voornaam = een map met je voornaam maken. WinSCP = een programma om bestanden te slepen tussen Windows en Linux. Daarna kijk je in de SSH-terminal (met ls) of het bestand er staat." },
  { v: "Waarop werken we in de Linux-werkcolleges, en met welk programma zet je die aan en uit?", a: "Op individuele Linux virtuele machines (VM's). Je beheert ze met de Virtual Machine Manager (in het startmenu van de EhB-computers).", o: "VM en SSH",
    uitleg: "Je maakt verbinding met de virtualisatiecluster met je persoonlijke EhB-credentials. Daar zie je al je VM's." },
  { v: "Waarop moet je letten bij het inloggen en typen in Linux?", a: "In Linux is zowat alles hoofdlettergevoelig: commando's, bestandsnamen, maar ook de username en het paswoord.", o: "VM en SSH",
    uitleg: "ls en LS zijn dus niet hetzelfde, en Tekst.txt en tekst.txt zijn twee verschillende bestanden." },
  { v: "Wat is een betere manier dan de console om de VM te beheren?", a: "Vanop afstand via het SSH-protocol.", o: "VM en SSH",
    uitleg: "Daarvoor moet op de machine die je wil beheren Open-SSH geïnstalleerd zijn (bijna altijd het geval), en op je eigen computer een SSH-client, zoals Windows Terminal of PowerShell." },
  { v: "Wat is de syntax van ssh, en wat betekent elk deel?", a: "ssh username@computername -p poort\nssh: het commando\nusername: de gebruiker op de remote computer\ncomputername: naam of IP-adres van de remote computer\npoort: de poort waarlangs je binnenkomt", o: "VM en SSH",
    uitleg: "Inloggen = 'op welke machine?' (naam of IP-adres + poort) en 'wie ben ik?' (username + paswoord). De gegevens van je eigen VM staan op Canvas." },
  { v: "Wat is de standaardpoort van SSH?", a: "Poort 22.", o: "VM en SSH",
    uitleg: "Het kan ook een andere poort zijn, afhankelijk van de situatie. Die geef je dan mee met -p." },
  { v: "Waarmee kopieer je bestanden van je Windows-pc naar de Linux-VM in de opdracht?", a: "Met WinSCP.", o: "VM en SSH",
    uitleg: "Opdracht: maak in Notepad een tekstbestand, kopieer het met WinSCP naar je persoonlijke map in je homefolder, en controleer in je SSH-terminal (met ls) of het goed is aangekomen." },
  { v: "Maak in je homedirectory een map met je voornaam (bv. jan).", a: "$ mkdir jan", o: "VM en SSH", oefening: true,
    uitleg: "mkdir = make directory. Na het inloggen sta je meteen in je homedirectory, dus je hoeft geen pad te geven." },
  { v: "Schrijf de syntax van ssh.", a: "$ ssh gebruiker@computernaam -p poort", o: "VM en SSH", oefening: true,
    uitleg: "gebruiker = de username op de remote computer, computernaam = naam of IP-adres, poort = de poort waarlangs je binnenkomt (normaal 22)." },
  { v: "Controleer of het gekopieerde bestand in je map jan staat.", a: "$ ls jan", o: "VM en SSH", oefening: true },
  { v: "Welke poort gebruikt SSH normaal gezien?", a: "Poort 22, maar het kan ook anders zijn, afhankelijk van de situatie.", o: "VM en SSH",
    uitleg: "Een poort is als een deurnummer op een computer: elke dienst luistert op zijn eigen poort." },
  { v: "Maak een folder in de homedirectory met jouw voornaam als naam", a: "$ mkdir jan", o: "VM en SSH", oefening: true,
    uitleg: "Vervang jan door je eigen voornaam. mkdir = make directory. Omdat je na het inloggen in je homedirectory staat, komt de nieuwe folder daar terecht." },
  { v: "Controleer via je SSH-terminal of het bestand is aangekomen.", a: "$ ls ~/jan", o: "VM en SSH", oefening: true,
    uitleg: "Vervang jan door je eigen voornaam. ~ = je homedirectory." },
  { v: "Geef de syntax van ssh om met een bepaalde poort te verbinden.", a: "ssh username@computername -p poort", o: "VM en SSH", examen: true,
    uitleg: "ssh = Secure Shell: een versleutelde verbinding naar de command line van een andere computer.\nusername = de gebruiker op de remote computer.\ncomputername = de naam of het IP-adres van die computer.\n-p poort = de poort, als het niet de standaardpoort 22 is.\n\nEen @ verbindt de gebruiker met de computer, zonder spaties." },
  { v: "Geef het commando om als gebruiker jan te verbinden met de computer 192.168.1.50 via poort 2222.", a: "ssh jan@192.168.1.50 -p 2222", o: "VM en SSH", examen: true,
    uitleg: "Je volgt de syntax ssh username@computername -p poort:\njan = de gebruiker\n192.168.1.50 = het IP-adres van de computer\n-p 2222 = de poort\n\nZonder -p probeert ssh de standaardpoort 22.\n(De gebruiker, het IP-adres en de poort zijn voorbeeldwaarden.)" },
  { v: "Welke poort gebruikt SSH standaard?", a: "22", o: "VM en SSH", examen: true,
    uitleg: "SSH gebruikt standaard poort 22. Als de server op die poort luistert, hoef je -p niet te gebruiken.\nOp een gedeelde server of via een router krijg je vaak een andere poort, dan geef je ze mee met -p." },
  { v: "Wat moet geïnstalleerd zijn op de machine die je via SSH wil beheren, en wat op je eigen computer?", a: "Op de remote machine: OpenSSH (server). Op je eigen computer: een SSH-client (bv. Windows Terminal).", o: "VM en SSH", examen: true,
    uitleg: "SSH werkt met een server en een client.\nDe server (OpenSSH server, de dienst sshd) draait op de machine die je wil beheren en luistert naar verbindingen.\nDe client draait op je eigen computer en maakt de verbinding: Windows Terminal, PowerShell of PuTTY.\nIn Windows 10 en 11 zit een ssh-client standaard ingebouwd." },
  { v: "Met welk programma kopieer je bestanden van Windows naar je Linuxmachine in het werkcollege?", a: "WinSCP.", o: "VM en SSH", examen: true,
    uitleg: "WinSCP is een grafisch programma voor Windows om bestanden te kopiëren naar en van een Linuxmachine. Het gebruikt SFTP of SCP, die over SSH werken.\nJe ziet links je eigen bestanden en rechts die van de Linuxmachine, en je sleept bestanden van de ene kant naar de andere." },
  { v: "Waar of niet waar: SSH is de afkorting die altijd hoort bij Windows Remote Desktop.", a: "Niet waar. Bij Remote Desktop hoort RDP. SSH (Secure Shell) gebruik je voor de Linux-CLI op afstand.", o: "VM en SSH", examen: true,
    uitleg: "RDP (Remote Desktop Protocol) is het protocol van Microsoft om het volledige bureaublad van een Windows-computer op afstand over te nemen.\nSSH (Secure Shell) geeft je een versleutelde command line op een andere computer, meestal Linux. Er is geen grafisch bureaublad." },
  // ===== De commandoshell Bash =====
  { v: "De commandoshell Bash (2)", a: "• Na het inloggen zie je een command prompt met een knipperende cursor: de commandoshell van Linux, bash.\n• Goed te vergelijken met MS-DOS.\n• Op Linux-servers werkt men nog het meest met de shell:\n– sneller dan met vensters\n– commando's makkelijk automatiseren met scripts\n– geen grafische omgeving die veel geheugen inneemt\n– kleinere attack surface: veiliger", o: "De commandoshell Bash", wit: true,
    uitleg: "Attack surface = alle plaatsen waar een aanvaller zou kunnen binnendringen. Minder software = minder kwetsbaarheden." },
  { v: "Wat is bash?", a: "De commandoshell van Linux: na het inloggen zie je een command prompt met een knipperende cursor. De shell interpreteert de commando's die je intypt.", o: "De commandoshell Bash",
    uitleg: "Bash is goed te vergelijken met MS-DOS (of de opdrachtprompt van Windows)." },
  { v: "Waarom wordt op Linux-servers nog steeds het meest met de commandoshell gewerkt?", a: "Je werkt sneller dan met vensters, je kan commando's makkelijk automatiseren met scripts, het systeem wordt niet nodeloos belast met een grafische omgeving die veel geheugen inneemt, en het zorgt voor een kleinere attack surface (beter voor de veiligheid).", o: "De commandoshell Bash",
    uitleg: "Attack surface = alle plaatsen waar een aanvaller zou kunnen binnendringen. Minder software = minder kwetsbaarheden." },
  { v: "Wat zie je nadat je ingelogd bent?", a: "Een command prompt met daarachter een knipperende cursor: je bent in de commandoshell van Linux, bash.", o: "De commandoshell Bash",
    uitleg: "De prompt ziet er bv. zo uit: student@linux:~$ (gebruiker@computer:huidige map$)." },
  { v: "Met wat is bash goed te vergelijken?", a: "Met MS-DOS.", o: "De commandoshell Bash",
    uitleg: "MS-DOS is de oude commandoregel van Windows (de voorloper van cmd)." },
  { v: "Wie interpreteert de commando's?", a: "De shell.", o: "De commandoshell Bash",
    uitleg: "Je typt tekst, de shell begrijpt welk programma moet starten en met welke opties en argumenten." },
  { v: "Hoe heet de commandoshell van Linux en met wat kan je ze vergelijken?", a: "bash, te vergelijken met MS-DOS.", o: "De commandoshell Bash" },
  { v: "Geef drie redenen waarom op Linux-servers vooral met de shell gewerkt wordt.", a: "Sneller werken en makkelijk automatiseren met scripts · geen geheugen verspild aan een grafische omgeving · kleiner attack-surface (veiliger).", o: "De commandoshell Bash" },
  { v: "Kan je de commando's uit deze les ook op een Mac gebruiken? Waarom?", a: "Ja, via de terminal: Mac OS X is net als Linux gebaseerd op Unix.", o: "De commandoshell Bash" },
  // ===== Structuur van commando's =====
  { v: "De structuur van Linux-commando's (2.1)", a: "• De shell interpreteert de commando's.\n• Een commando kan zonder opties of parameters, maar dan gebeurt er vaak niet veel, of juist te veel (bv. find).\n• Opties: extra informatie over HOE het commando moet werken. Vast ingeprogrammeerd, je kan er zelf geen toevoegen. Ze beginnen bijna steeds met een '-'.\n• Argumenten: variabele waarden, meestal WAAROP het commando werkt.\n\nVoorbeeld: ls -h -a -l /home/student\nls = commando · -h, -a, -l = opties · /home/student = argument", o: "Structuur van commando's", wit: true,
    uitleg: "Een commando is eigenlijk een programma." },
  { v: "Wat zijn opties bij een Linux-commando?", a: "Extra stukjes informatie die zeggen HOE je wil dat het commando uitgevoerd wordt. Ze zijn vast in het programma geprogrammeerd (je kan er zelf geen bijmaken) en beginnen bijna altijd met een '-'.", o: "Structuur van commando's",
    uitleg: "Een commando is eigenlijk een programma. Bv. -l bij ls betekent 'lange lijst met details'." },
  { v: "Wat zijn argumenten bij een Linux-commando?", a: "Variabele waarden die je meegeeft om het gedrag verder te specifiëren. Meestal gaat het over WAAROP het commando toegepast moet worden.", o: "Structuur van commando's",
    uitleg: "Bv. de map waarvan je de inhoud wil zien, of het bestand dat je wil openen. Argument = parameter." },
  { v: "Benoem de delen in: ls -h -a -l /home/student", a: "ls = het commando\n-h, -a en -l = 3 verschillende opties\n/home/student = een argument", o: "Structuur van commando's",
    uitleg: "-h = human readable (grootte in K, M, G), -a = all (ook verborgen bestanden), -l = long (details). Opties mag je ook samenvoegen: ls -hal." },
  { v: "Kan je een commando gebruiken zonder opties of parameters?", a: "Ja, maar bij veel commando's gebeurt er dan niet veel, of juist te veel (bv. find).", o: "Structuur van commando's",
    uitleg: "find zonder argumenten toont bv. alle bestanden onder de huidige map, wat een enorme lijst kan zijn." },
  { v: "Wat is het verschil tussen een optie en een argument?", a: "Een optie zegt HOE het commando werkt (vast ingeprogrammeerd, begint meestal met -). Een argument is een variabele waarde, meestal WAAROP het commando werkt.", o: "Structuur van commando's" },
  { v: "Kan je zelf opties aan een commando toevoegen? Waarom (niet)?", a: "Nee: opties zijn vast in het programma geprogrammeerd (een commando is een programma).", o: "Structuur van commando's" },
  { v: "Let op bij examenvragen die om een commando vragen: wat is de vereiste?", a: "Het antwoord moet gecopy-past kunnen worden en effectief werken: syntax en spelling (ook hoofdletters in Linux) zijn belangrijk.", o: "Structuur van commando's", examen: true,
    uitleg: "Op het examen controleert men of je commando echt werkt als men het kopieert en plakt.\nLet dus op:\nde juiste spaties tussen commando, opties en argumenten\nhoofdletters en kleine letters (Linux is hoofdlettergevoelig)\nde juiste schuine streep: / in Linux, \\ in Windows\nsudo als het commando root-rechten nodig heeft" },
  { v: "Wat is de algemene structuur van een Bash-commando?", a: "commando -optie parameter (argument)", o: "Structuur van commando's", examen: true,
    uitleg: "Eerst het commando zelf (wat moet er gebeuren), dan de opties (hoe het moet gebeuren, meestal met een -), dan de argumenten (waarop het moet gebeuren).\nVoorbeeld: ls -l /etc\nls = commando, -l = optie (lange weergave), /etc = argument (de map)." },
  { v: "In \"ls -h -a -l /home/student\": wat is het commando, wat zijn de opties en wat is het argument?", a: "Commando: ls. Opties: -h, -a, -l. Argument: /home/student.", o: "Structuur van commando's", examen: true,
    uitleg: "ls = het commando (toon de inhoud van een map).\n-h = human readable: groottes in K, M en G.\n-a = all: ook verborgen bestanden.\n-l = long: details zoals rechten en eigenaar.\n/home/student = het argument: de map waarvan je de inhoud wil zien.\n\nOpties mag je samenvoegen: ls -hal /home/student doet hetzelfde." },
  { v: "Leg uit: wat is het verschil tussen een optie en een argument bij een Bash-commando?", a: "Een optie (meestal met -) is vast in het programma ingebouwd en zegt hoe het commando werkt. Een argument is een variabele waarde, meestal waarop het commando toegepast wordt.", o: "Structuur van commando's", examen: true,
    uitleg: "Opties zijn vast ingeprogrammeerd: je kan er zelf geen bijmaken. Je vindt ze in man of met --help.\nArgumenten kies je zelf: een bestandsnaam, een map, een gebruikersnaam.\nIn ls -l /etc is -l een optie en /etc een argument." },
  // ===== Eerste commando's en tips =====
  { v: "Eerste commando's (2.1)", a: "Probeer meteen een aantal commando's uit:\n• who toont de ingelogde gebruikers\n• whoami toont je eigen loginnaam\n• date toont de ingestelde datum en tijd", o: "Eerste commando's en tips", wit: true },
  { v: "Tip: vorige commando's herhalen (2.1)", a: "Met de pijltjestoetsen ↑ en ↓ herhaal je vorige commando's.", o: "Eerste commando's en tips", wit: true },
  { v: "Tip: tab-completion (2.1)", a: "TAB vult een commando, directory of bestand aan. Typ bv. vi + Tab: je ziet alle commando's die met vi beginnen. Is er maar 1 mogelijkheid, dan vult bash volledig aan.", o: "Eerste commando's en tips", wit: true },
  { v: "Wat doen who, whoami en date?", a: "who: toont de ingelogde gebruikers.\nwhoami: toont je eigen loginnaam.\ndate: toont de ingestelde datum en tijd.", o: "Eerste commando's en tips",
    uitleg: "whoami is handig als je met su van gebruiker gewisseld bent (werkcollege 3)." },
  { v: "Wat doen de pijltjestoetsen ↑ en ↓ in bash?", a: "Je vorige commando's terug oproepen (herhalen).", o: "Eerste commando's en tips",
    uitleg: "Extra uit je samenvatting: Ctrl+R en beginnen typen zoekt achterwaarts in je vorige commando's." },
  { v: "Wat is tab-completion?", a: "Met de TAB-toets vult bash je commando, directory of bestandsnaam aan wanneer dat mogelijk is. Is er maar 1 mogelijkheid, dan vult bash volledig aan.", o: "Eerste commando's en tips",
    uitleg: "Typ je bv. vi en druk je op TAB (twee keer), dan zie je alle commando's die met vi beginnen. cd /ho + TAB wordt cd /home." },
  { v: "Toon wie er ingelogd is.", a: "$ who", o: "Eerste commando's en tips", oefening: true },
  { v: "Toon de datum en de tijd.", a: "$ date", o: "Eerste commando's en tips", oefening: true },
  { v: "Haal je vorige commando terug zonder het opnieuw te typen.", a: "  ↑\n  ↓", o: "Eerste commando's en tips", oefening: true,
    uitleg: "Met ↑ ga je terug naar vorige commando's, met ↓ weer vooruit." },
  { v: "Toon alle commando's die met vi beginnen.", a: "$ vi\n  Tab", o: "Eerste commando's en tips", oefening: true,
    uitleg: "Typ vi en druk op de Tab-toets (eventueel twee keer)." },
  { v: "Vul cd /ho automatisch aan tot cd /home.", a: "$ cd /ho\n  Tab\n$ cd /home", o: "Eerste commando's en tips", oefening: true,
    uitleg: "Tab-completion: bash vult zelf aan als er maar 1 mogelijkheid is." },
  { v: "Hoe haal je een vorig commando terug zonder het opnieuw te typen?", a: "Met de pijltjestoetsen ↑ en ↓.", o: "Eerste commando's en tips" },
  { v: "Toon je eigen loginnaam.", a: "$ whoami", o: "Eerste commando's en tips", oefening: true },
  { v: "Waar of niet waar: Linux is hoofdlettergevoelig, ook voor username en paswoord.", a: "Waar. Commando's, bestandsnamen, usernames en paswoorden zijn hoofdlettergevoelig.", o: "Eerste commando's en tips", examen: true,
    uitleg: "In Linux zijn Bestand.txt, bestand.txt en BESTAND.TXT drie verschillende bestanden.\nOok commando's: LS werkt niet, ls wel.\nUsernames en paswoorden zijn ook hoofdlettergevoelig.\nIn Windows (CMD) maakt het voor bestandsnamen en commando's niet uit." },
  { v: "Wat doet de TAB-toets in Bash?", a: "Tab-completion: vult commando, directory of bestand aan. Bij meerdere mogelijkheden toont hij ze.", o: "Eerste commando's en tips", examen: true,
    uitleg: "Tab-completion bespaart typwerk en voorkomt typfouten.\nTyp het begin van een commando, map of bestand en druk op Tab: Bash vult de rest aan.\nZijn er meerdere mogelijkheden, dan gebeurt er eerst niets. Druk nog eens op Tab en Bash toont alle mogelijkheden.\nIn CMD werkt Tab ook: daar ga je bij elke druk naar de volgende mogelijkheid." },
  { v: "Hoe roep je vorige commando's terug op in Bash?", a: "Met de pijltjestoetsen omhoog en omlaag.", o: "Eerste commando's en tips", examen: true,
    uitleg: "Met pijltje omhoog ga je terug naar het vorige commando, nog eens omhoog naar het commando daarvoor. Met pijltje omlaag ga je terug vooruit.\nBash houdt die geschiedenis bij. Met het commando history zie je de hele lijst." },
  { v: "Wat tonen who, whoami en date?", a: "who: de ingelogde gebruikers. whoami: je eigen loginnaam. date: de ingestelde datum en tijd.", o: "Eerste commando's en tips", examen: true,
    uitleg: "who toont alle gebruikers die nu ingelogd zijn, met hun terminal en het tijdstip van inloggen.\nwhoami toont enkel je eigen loginnaam. Handig na su om te controleren als wie je nu werkt.\ndate toont de ingestelde datum en tijd van het systeem." },
  // ===== man en --help =====
  { v: "Hulp in Linux: man (3)", a: "• Linux heeft veel bronnen met informatie ingebakken, ook in de CLI.\n• man commando toont de manual page (handleiding), bv. man ls.\n• Navigeren met de pijltjestoetsen, page up en page down; verlaten met q.\n• Gebruik de man pages zo veel mogelijk: het zijn de help-files van het Linux-systeem.\n• Andere hulp: info, whatis en de optie --help.", o: "man en --help", wit: true },
  { v: "Hulp in Linux: --help (3)", a: "--help geeft snel een overzicht van de meest gebruikte parameters en opties.", o: "man en --help", wit: true,
    uitleg: "In de cursus staat '–help'; de juiste schrijfwijze is met twee streepjes: --help." },
  { v: "Hoe roep je de handleiding van een commando op, bv. van ls?", a: "$ man ls", o: "man en --help", oefening: true,
    uitleg: "man = manual (handleiding). Het zijn de help-files van het Linux-systeem: je vindt er zowat alle informatie in die je nodig hebt." },
  { v: "Hoe navigeer je in een man-page, en hoe verlaat je ze?", a: "Navigeren met de pijltjestoetsen, page up en page down, … Verlaten met de letter q.", o: "man en --help",
    uitleg: "In een man-page kan je ook zoeken met /woord (zoals in less)." },
  { v: "Wat doet de optie --help bij een commando?", a: "Ze geeft snel een overzicht van de meest gebruikte parameters en opties van dat commando.", o: "man en --help",
    uitleg: "Bv. ls --help. Wat tussen [ ] staat, is optioneel. In de cursus staat soms '–help' of '-help', maar de juiste schrijfwijze is met twee streepjes: --help." },
  { v: "Verlaat een man-page.", a: "  q", o: "man en --help", oefening: true },
  { v: "Toon een korte uitleg van ls in 1 regel.", a: "$ whatis ls", o: "man en --help", oefening: true },
  { v: "Toon snel een overzicht van de opties van ls.", a: "$ ls --help", o: "man en --help", oefening: true },
  { v: "Zoek op 3 manieren hulp over mkdir.", a: "$ man mkdir\n$ mkdir --help\n$ whatis mkdir", o: "man en --help", oefening: true },
  { v: "Wat heeft Linux ingebakken in het operating system, ook in de CLI?", a: "Veel bronnen met informatie (hulp).", o: "man en --help",
    uitleg: "Je hebt dus geen internet nodig om de werking van een commando op te zoeken." },
  { v: "Waar staat 'man' voor en hoe roep je het op?", a: "Manual (in het Nederlands: handleiding). Je typt man commando, bv. man ls toont de manual page van ls.", o: "man en --help",
    uitleg: "In de cursus staat de tikfout 'hanleiding'." },
  { v: "Waarvoor gebruik je de man pages best?", a: "Zo veel mogelijk, wanneer je de werking van een commando niet goed begrijpt. Het zijn de help-files van het Linux-systeem: je vindt er zowat alle informatie die nodig is voor het gebruik van Linux.", o: "man en --help",
    uitleg: "Een man page heeft vaste delen: NAME, SYNOPSIS (syntax), DESCRIPTION (uitleg en opties), EXAMPLES, SEE ALSO." },
  { v: "Zoek hulp over cd.", a: "$ help cd\n$ whatis cd", o: "man en --help", oefening: true,
    uitleg: "cd zit ingebouwd in bash, daarom werkt help cd." },
  { v: "Zoek hulp over het wijzigen van je paswoord.", a: "$ man passwd\n$ whatis passwd", o: "man en --help", oefening: true },
  { v: "Test de hulpcommando's op elkaar.", a: "$ whatis man\n$ whatis info\n$ man whatis\n$ man info\n$ info man", o: "man en --help", oefening: true },
  { v: "Welk commando toont de handleiding (manual pages) van een commando?", a: "man commando (bv. man ls)", o: "man en --help", examen: true,
    uitleg: "man is de afkorting van manual. man ls toont de handleiding van ls: de syntax, een beschrijving en alle opties.\nJe scrolt met de pijltjes of de spatiebalk, je zoekt met /zoekwoord en je sluit af met q." },
  { v: "Hoe verlaat je een man page?", a: "Met de letter q.", o: "man en --help", examen: true,
    uitleg: "Een man page wordt getoond in een pager (meestal less). Met q (quit) sluit je die af en kom je terug in de shell.\nIn de man page zoek je met /woord en spring je naar het volgende resultaat met n." },
  { v: "Welk hulpcommando toont ook algemene concepten?", a: "info", o: "man en --help", examen: true,
    uitleg: "info toont uitgebreidere documentatie dan man, met hyperlinks tussen pagina's, en gaat ook in op algemene concepten.\nVoorbeeld: info ls" },
  { v: "Welk hulpcommando geeft een beknoptere uitleg?", a: "whatis", o: "man en --help", examen: true,
    uitleg: "whatis toont een beschrijving van één regel uit de man page.\nVoorbeeld: whatis ls toont: ls (1) - list directory contents\nHandig om snel te weten wat een commando doet, zonder de hele man page te lezen." },
  { v: "Met welke optie krijg je bij veel commando's een overzicht van syntax en voornaamste opties?", a: "--help (bv. ls --help)", o: "man en --help", examen: true,
    uitleg: "--help (twee streepjes) toont een kort overzicht van de syntax en de voornaamste opties, rechtstreeks in de terminal.\nVoorbeeld: ls --help\nIn Windows CMD is het equivalent: commando /?, bv. dir /?" },
  { v: "Geef het commando om de manual page van chmod te openen.", a: "man chmod", o: "man en --help", examen: true,
    uitleg: "man gevolgd door de naam van het commando: man chmod.\nJe ziet dan de syntax, de beschrijving van de symbolische en de octale (cijfer)methode en alle opties. Sluiten doe je met q." },
  // ===== Het bestandssysteem =====
  { v: "Het Linux-bestandssysteem (4)", a: "• Een vaste structuur: bestanden in directories en subdirectories, voor te stellen als een boom.\n• De root is / en niet C:\\.\n• Geen driveletters: partities en netwerkfolders hangen allemaal onder dezelfde /.\n• In / zitten subdirectories, meestal door het systeem vastgelegd (bv. usr; bin is een subdirectory van usr).\n• cd (change directory) wisselt van directory, pwd toont de huidige werkdirectory.", o: "Het bestandssysteem", wit: true, img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Zie de boomfiguur: / met daaronder etc, usr, home en bin." },
  { v: "Opdracht: navigeren met cd (4). Wat doen cd /usr/local, cd .., cd ../.., ls, cd en pwd?", a: "• cd /usr/local: naar een andere directory gaan\n• cd ..: 1 directory terug\n• cd ../..: 2 directories terug\n• ls: de inhoud van de huidige werkdirectory\n• cd: terug naar je homedirectory\n• pwd: de huidige werkdirectory tonen", o: "Het bestandssysteem", oefening: true,
    uitleg: "cd = change directory: naar een andere map gaan. .. = de map erboven. ls = list: de inhoud tonen. cd zonder iets erachter = naar je homedirectory. pwd = print working directory: in welke map sta je nu?" },
  { v: "Wat toont deze figuur, en wat is de root?", a: "De boomstructuur van het Linux-bestandssysteem. De root (wortel, bovenaan) is /. Daaronder staan mappen zoals etc, usr, home en bin; usr heeft submappen bin en doc, home heeft Kris en tim.", o: "Het bestandssysteem", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Linux heeft 1 boomstructuur, het VFS (virtual file system). Alles hangt onder / , ook andere schijven en netwerkmappen." },
  { v: "Wat is het grote verschil tussen het bestandssysteem van Linux en dat van Windows?", a: "De root van Linux is / en niet C:\\. Linux heeft geen driveletters: waar in Windows elke letter een aparte partitie of netwerkmap is, worden die in Linux allemaal onder dezelfde / geplaatst.", o: "Het bestandssysteem",
    uitleg: "Een USB-stick of tweede schijf verschijnt in Linux gewoon als een map ergens in de boom (bv. /media/usbstick)." },
  { v: "Met welk commando wissel je van directory, en hoe controleer je waar je bent?", a: "cd (change directory) om te wisselen; pwd (print working directory) om je huidige werkdirectory te tonen.", o: "Het bestandssysteem",
    uitleg: "Voorbeeld: vanuit / geeft cd usr/local als resultaat dat je in /usr/local zit. Controle: pwd." },
  { v: "Wat doen cd .. en cd ../.. ?", a: "cd .. gaat 1 directory terug (naar de ouderdirectory). cd ../.. gaat 2 directories terug.", o: "Het bestandssysteem",
    uitleg: "Bv. vanuit /usr/local/bin brengt cd ../.. je naar /usr." },
  { v: "Wat doet cd zonder argument?", a: "Het brengt je terug naar je homedirectory.", o: "Het bestandssysteem",
    uitleg: "Dat is de kortste manier om naar huis te gaan. cd ~ doet hetzelfde." },
  { v: "Wat doet cd . ?", a: "Niets: . is de huidige directory, dus je blijft waar je bent.", o: "Het bestandssysteem",
    uitleg: "De . is vooral nuttig in een pad, bv. ./script.sh = 'voer script.sh uit uit DEZE map'." },
  { v: "Ga naar de root.", a: "$ cd /", o: "Het bestandssysteem", oefening: true },
  { v: "Toon in welke directory je nu zit.", a: "$ pwd", o: "Het bestandssysteem", oefening: true,
    uitleg: "pwd = print working directory." },
  { v: "Huidige directory", a: ".", o: "Het bestandssysteem" },
  { v: "Ga naar /usr/local/bin.", a: "$ cd /usr/local/bin", o: "Het bestandssysteem", oefening: true },
  { v: "Hoeveel boomstructuren heeft het Linux-bestandssysteem?", a: "1 boomstructuur (VFS).", o: "Het bestandssysteem",
    uitleg: "VFS = Virtual File System: één virtuele boom waarin alle schijven en partities samenkomen." },
  { v: "Gebruikt Linux driveletters zoals Windows?", a: "Nee, geen driveletters.", o: "Het bestandssysteem",
    uitleg: "In Windows heeft elke schijf een letter (C:, D:). In Linux komt alles onder /, bv. een USB-stick onder /media/usb." },
  { v: "Wat doen mkdir, rmdir en rm?", a: "mkdir maakt een directory, rmdir verwijdert een lege directory, rm verwijdert bestanden.", o: "Het bestandssysteem",
    uitleg: "rm -r verwijdert ook een directory met inhoud. Er is geen prullenbak!" },
  { v: "Wie legt de subdirectories in / meestal vast?", a: "Het systeem.", o: "Het bestandssysteem",
    uitleg: "Bv. usr is een subdirectory van /; bin is dan weer een subdirectory van usr." },
  { v: "Wat is het resultaat van cd usr/local vanuit /, en hoe controleer je dat?", a: "De huidige werkdirectory is nu /usr/local. Je controleert dat met pwd.", o: "Het bestandssysteem",
    uitleg: "usr/local is hier een relatief pad (zonder / vooraan) dat vanuit / naar /usr/local leidt." },
  { v: "Op hoeveel manieren kan je een plaats in de structuur aanduiden? Welke?", a: "Op 2 manieren: met een absoluut pad en met een relatief pad.", o: "Het bestandssysteem",
    uitleg: "Of met ~ als afkorting voor je homedirectory (zie 4.2)." },
  { v: "Wat is de root van het Linux-bestandssysteem? Wat is het verschil met Windows?", a: "/ (niet C:\\). In Linux hangen alle partities en netwerkmappen onder dezelfde /, in plaats van aparte letters.", o: "Het bestandssysteem" },
  { v: "Controleer in welke directory je zit.", a: "$ pwd", o: "Het bestandssysteem", oefening: true,
    uitleg: "Resultaat: /usr/local." },
  { v: "Ga één directory terug.", a: "$ cd ..", o: "Het bestandssysteem", oefening: true,
    uitleg: "Je zit nu in /usr." },
  { v: "Toon de inhoud van de huidige directory.", a: "$ ls", o: "Het bestandssysteem", oefening: true },
  { v: "Waarvoor staan .. en . in een pad?", a: ".. = ouderdirectory (1 niveau dichter bij /) · . = huidige directory", o: "Het bestandssysteem" },
  { v: "Waar of niet waar: Linux gebruikt driveletters zoals C:\\ en D:\\.", a: "Niet waar. Linux heeft één boomstructuur (VFS) vanaf de root /, zonder driveletters.", o: "Het bestandssysteem", examen: true,
    uitleg: "Linux heeft één boomstructuur, het VFS (Virtual File System). Alles begint bij de root /.\nEen tweede schijf, een USB-stick of een netwerkmap krijgt geen letter, maar wordt gemount (gekoppeld) op een map in die boom, bv. /mnt/usb.\nWindows gebruikt wel letters zoals C:\\ en D:\\." },
  { v: "Wat is de root van het Linux-bestandssysteem?", a: "/", o: "Het bestandssysteem", examen: true,
    uitleg: "De root / is het hoogste punt van de boomstructuur. Alle andere mappen zitten eronder: /home, /etc, /usr, /var, /root, …\nLet op: / (de root van het bestandssysteem) is iets anders dan /root (de homedirectory van de gebruiker root)." },
  { v: "Waar komen partities en netwerkfolders terecht in Linux?", a: "Allemaal onder dezelfde / (gemount in de boomstructuur).", o: "Het bestandssysteem", examen: true,
    uitleg: "Elke partitie, schijf of netwerkfolder wordt gemount: gekoppeld aan een map in de boomstructuur onder /.\nVoorbeeld: een USB-stick kan je mounten op /mnt/usb. Daarna zie je de bestanden van de stick in die map." },
  { v: "Gegeven uit de help van mount:\nmount [options] <source> <directory>\n-t, --types <list>   limit the set of filesystem types\n-r, --read-only      mount the filesystem read-only\n\nMount /dev/sda1 naar /mnt/DISK2, in ntfs met filesystem type ntfs-3g.", a: "sudo mount -t ntfs-3g /dev/sda1 /mnt/DISK2", o: "Het bestandssysteem", examen: true,
    uitleg: "Je volgt de syntax uit de help: mount [options] <source> <directory>.\nsudo: mounten vraagt root-rechten.\n-t ntfs-3g: het type bestandssysteem.\n/dev/sda1: de source, de eerste partitie van de eerste schijf.\n/mnt/DISK2: de directory waar de partitie zichtbaar wordt (mountpoint).\nLet op de hoofdletters in DISK2." },
  { v: "Mount /dev/sdb1 read-only naar /mnt/usb.", a: "sudo mount -r /dev/sdb1 /mnt/usb", o: "Het bestandssysteem", examen: true,
    uitleg: "-r = read-only: je kan de bestanden lezen, maar niets wijzigen of verwijderen.\n/dev/sdb1: de eerste partitie van de tweede schijf (bv. een USB-stick).\n/mnt/usb: het mountpoint. Die map moet al bestaan (sudo mkdir /mnt/usb).\nMet sudo umount /mnt/usb maak je de koppeling ongedaan." },
  { v: "Wat betekent mounten?", a: "Een partitie of schijf koppelen aan een directory (mountpoint) in de boomstructuur.", o: "Het bestandssysteem", examen: true,
    uitleg: "Linux heeft één boomstructuur vanaf /. Een partitie of schijf wordt zichtbaar door ze te koppelen aan een (lege) map: het mountpoint.\nNa het mounten zie je de bestanden van de schijf in die map.\nMet mount zonder opties en met df -h zie je wat gemount is. Wat bij het opstarten automatisch gemount wordt, staat in /etc/fstab." },
  // ===== Absoluut en relatief pad =====
  { v: "Absoluut of relatief pad (4.1)", a: "• Absoluut pad: een volledige verwijzing, begint steeds vanaf de root /. Bv. /usr/local.\n• Relatief pad: begint vanaf de huidige positie en kan korter zijn. Vanuit /usr verwijs je naar local gewoon met local.\n• .. = de ouderdirectory (1 niveau dichter bij /)\n• . = de huidige directory\n• Voorbeeld: vanuit /usr/local is het relatieve pad naar /usr/src ../src.", o: "Absoluut en relatief pad", wit: true,
    uitleg: "Volgens de cursus zeer belangrijk: je komt ze overal tegen (programmeren, webpagina's, hyperlinks, ...). Linux gebruiken zonder absolute en relatieve paden is onmogelijk." },
  { v: "Wat is een absoluut pad?", a: "Een volledige verwijzing naar een bepaalde directory in het systeem. Een absoluut pad begint altijd vanaf de root / .", o: "Absoluut en relatief pad",
    uitleg: "Voorbeeld: /usr/local. Het werkt overal, ongeacht waar je je bevindt. Je samenvatting zegt: navigatie en relatieve paden zijn belangrijk voor het examen!" },
  { v: "Wat is een relatief pad, en waarom gebruik je het?", a: "Een verwijzing die begint vanaf je huidige positie. Het kan korter zijn dan het absolute pad.", o: "Absoluut en relatief pad",
    uitleg: "Vanuit /usr verwijs je naar /usr/local gewoon met local. Een relatief pad begint dus NIET met /." },
  { v: "Wat betekenen .. en . in een relatief pad?", a: ".. = de ouderdirectory (1 niveau dichter bij de root /).\n. = de huidige directory.", o: "Absoluut en relatief pad",
    uitleg: "In de tekst van de cursus staat 'dichter bij ?': bedoeld is de root /." },
  { v: "Je bent in /usr/local. Wat is het relatieve pad naar /usr/src?", a: "../src", o: "Absoluut en relatief pad",
    uitleg: "Eerst één niveau omhoog naar /usr (..), dan naar beneden in src." },
  { v: "Je bent in /usr/local/bin en wil naar /usr/src. Geef een absoluut en een relatief pad.", a: "Absoluut: cd /usr/src\nRelatief: cd ../../src", o: "Absoluut en relatief pad",
    uitleg: "Twee keer omhoog (bin → local → usr) en dan src in. In het oplossingendocument staat als relatief pad 'cd ../local/bin': dat klopt niet (dat brengt je terug naar /usr/local/bin). Juist is ../../src." },
  { v: "Wat is het absolute pad van de map Kris in deze boomstructuur?", a: "/home/Kris", o: "Absoluut en relatief pad", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Begin bij de root /, ga naar home, dan Kris. Let op: Linux is hoofdlettergevoelig, dus /home/kris zou een andere map zijn." },
  { v: "Je zit in /home/tim. Wat is het relatieve pad naar /usr/doc?", a: "../../usr/doc", o: "Absoluut en relatief pad", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Eén keer omhoog naar /home, nog een keer omhoog naar / , dan naar usr en doc. Absoluut zou het /usr/doc zijn." },
  { v: "Je zit in /usr/bin. Wat is het relatieve pad naar /home/Kris?", a: "../../home/Kris", o: "Absoluut en relatief pad", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Omhoog naar /usr, omhoog naar /, dan home en Kris. Tip: tel hoeveel niveaus je omhoog moet tot je een gemeenschappelijke map bereikt (hier /), en ga dan naar beneden." },
  { v: "Je zit in /home. Wat is het relatieve pad naar tim?", a: "tim (of ./tim)", o: "Absoluut en relatief pad", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "tim is een submap van de huidige map, dus je hoeft niet omhoog. ./tim betekent hetzelfde: 'tim in de huidige map'." },
  { v: "Je zit in /home/Kris. Wat is het relatieve pad naar /home/tim?", a: "../tim", o: "Absoluut en relatief pad", img: "afbeeldingen/DesktopOS_linux_wc1/lx_boom.png",
    uitleg: "Eén niveau omhoog naar /home, dan naar tim: Kris en tim staan naast elkaar." },
  { v: "Je bent in /home/student. Waar kom je terecht met cd ../../etc ?", a: "In /etc", o: "Absoluut en relatief pad",
    uitleg: "../.. brengt je van /home/student naar / , en daarna ga je naar etc." },
  { v: "Begint een relatief pad met / ?\na) Ja, altijd\nb) Nee, het begint vanaf de huidige map\nc) Enkel als je in je homedirectory zit\nd) Enkel bij cd", a: "b) Nee, het begint vanaf de huidige map.", o: "Absoluut en relatief pad",
    uitleg: "Een pad dat met / begint is altijd absoluut. Een relatief pad begint met een mapnaam, met .. of met . (en ~ is een afkorting voor je homedirectory)." },
  { v: "Ga vanuit / met een relatief pad naar /usr/local.", a: "$ cd usr/local", o: "Absoluut en relatief pad", oefening: true },
  { v: "Ga 2 directories terug.", a: "$ cd ../..", o: "Absoluut en relatief pad", oefening: true },
  { v: "Hoe verwijs je vanuit /usr naar de subdirectory local met een relatief pad?", a: "Gewoon met local.", o: "Absoluut en relatief pad",
    uitleg: "Dit werkt evengoed als met een absoluut pad (/usr/local), maar de relatieve verwijzing is alleszins korter." },
  { v: "Waarom is het zo belangrijk absolute en relatieve paden goed te begrijpen?", a: "Overal binnen de informatica kom je ze tegen: bij het gebruik van bestanden of externe bibliotheken bij het programmeren, bij de ontwikkeling van webpagina's, bij hyperlinks, bij het linken van bestanden,… Linux gebruiken zonder te kunnen werken met absoluut en relatief pad is onmogelijk.", o: "Absoluut en relatief pad",
    uitleg: "Bv. in HTML: <img src=\"images/logo.png\"> is relatief, <img src=\"/images/logo.png\"> is absoluut (vanaf de root van de website)." },
  { v: "Ga vanuit /usr/local twee directories terug.", a: "$ cd ../..", o: "Absoluut en relatief pad", oefening: true,
    uitleg: "Je zit nu in /." },
  { v: "Wat is een absoluut pad? Geef het absolute pad van local.", a: "Een volledige verwijzing die altijd bij de root / begint: /usr/local", o: "Absoluut en relatief pad" },
  { v: "Welk commando toont de huidige werkdirectory?", a: "pwd", o: "Absoluut en relatief pad", examen: true,
    uitleg: "pwd = print working directory. Het toont het volledige (absolute) pad van de map waarin je nu staat, bv. /home/student.\nDe working directory is het vertrekpunt voor relatieve paden." },
  { v: "Welk commando toont de inhoud van een directory?", a: "ls", o: "Absoluut en relatief pad", examen: true,
    uitleg: "ls = list. Zonder argument toont het de inhoud van de huidige map, met een argument de inhoud van die map: ls /etc.\nVeelgebruikte opties: -l (details), -a (ook verborgen bestanden), -h (leesbare groottes)." },
  { v: "Wat doet cd ..?", a: "Eén directory terug (naar de ouderdirectory).", o: "Absoluut en relatief pad", examen: true,
    uitleg: ".. is de ouderdirectory: de map één niveau hoger.\nStaat je in /usr/local, dan brengt cd .. je naar /usr.\nLet op de spatie tussen cd en .. (in Linux is cd.. een fout)." },
  { v: "Wat doet cd ../..?", a: "Twee directories terug.", o: "Absoluut en relatief pad", examen: true,
    uitleg: "../.. betekent: twee keer de ouderdirectory, dus twee niveaus hoger.\nVan /usr/local/bin brengt cd ../.. je naar /usr." },
  { v: "Waar kom je terecht met cd zonder argument?", a: "Terug naar je homedirectory.", o: "Absoluut en relatief pad", examen: true,
    uitleg: "cd zonder argument brengt je altijd naar je eigen homedirectory, bv. /home/student.\nHetzelfde doet cd ~ (de tilde staat voor je homedirectory)." },
  { v: "Wat betekent . en wat betekent .. in een pad?", a: ". = de huidige directory. .. = de ouderdirectory.", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Elke map bevat twee speciale verwijzingen:\n. verwijst naar de map zelf (de huidige directory)\n.. verwijst naar de ouderdirectory (één niveau hoger)\nJe ziet ze met ls -a.\nVoorbeeld: cp opdracht/opdracht.txt . kopieert naar de huidige map." },
  { v: "Wat betekent ./ voor een bestandsnaam?", a: "In de huidige directory (bv. ./script.sh voert script.sh in de huidige map uit).", o: "Absoluut en relatief pad", examen: true,
    uitleg: "./ betekent: in de huidige directory.\nOm een script of programma in de huidige map uit te voeren, moet je ./ ervoor zetten: ./script.sh.\nZonder ./ zoekt Bash het programma enkel in de mappen van de PATH-variabele, en de huidige map zit daar niet in." },
  { v: "Wat verstaat men onder een absoluut pad?", a: "Een volledige verwijzing die altijd begint vanaf de root /, bv. /usr/local.", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Een absoluut pad begint altijd met /: het vertrekt vanaf de root.\nHet werkt overal, ongeacht in welke map je staat.\nVoorbeelden: /usr/local, /etc/passwd, /home/student/Documenten" },
  { v: "Wat is een relatief pad?", a: "Een verwijzing vanaf de huidige positie, bv. local als je in /usr staat.", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Een relatief pad begint niet met /. Het vertrekt vanaf de map waarin je nu staat (de working directory).\nStaat je in /usr, dan verwijst local naar /usr/local.\nMet .. ga je een niveau hoger: ../src vanuit /usr/local verwijst naar /usr/src." },
  { v: "Je zit in /usr/local. Geef het relatieve pad naar /usr/src.", a: "../src", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Vanuit /usr/local ga je eerst één niveau hoger met .. (dan ben je in /usr) en daarna naar src.\nDus: ../src\nHet absolute pad zou /usr/src zijn." },
  { v: "Je zit in /usr/local/bin. Geef het commando met relatief pad om naar /usr/src te gaan.", a: "cd ../../src", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Vanuit /usr/local/bin:\nde eerste .. brengt je naar /usr/local\nde tweede .. brengt je naar /usr\ndaarna ga je naar src\nDus: cd ../../src" },
  { v: "Je zit in /usr/local/bin. Geef het commando met absoluut pad om naar /usr/src te gaan.", a: "cd /usr/src", o: "Absoluut en relatief pad", examen: true,
    uitleg: "Een absoluut pad begint met / en werkt vanuit elke map: cd /usr/src.\nHet maakt niet uit dat je in /usr/local/bin staat." },
  { v: "Geef drie manieren om vanuit /usr/src naar je homedirectory (bv. /home/student) te gaan.", a: "cd   /   cd ~   /   cd /home/student   (of cd ../../home/student)", o: "Absoluut en relatief pad", examen: true,
    uitleg: "cd zonder argument: altijd naar je homedirectory.\ncd ~: de tilde staat voor je homedirectory.\ncd /home/student: het absolute pad.\ncd ../../home/student: het relatieve pad vanuit /usr/src (twee niveaus hoger tot /, dan home/student)." },
  // ===== Homedirectory =====
  { v: "Homedirectory (4.2)", a: "• Linux is multi-user: elke gebruiker heeft zijn eigen persoonlijke werkdirectory, waar enkel hij toegang toe heeft: de homedirectory.\n• Als guest: /home/guest; als joske: /home/joske.\n• cd zonder argument brengt je altijd naar je homedirectory.\n• Afkorting: ~ (tilde). /home/guest/doc = ~/doc (als guest).\n• whoami toont als welke gebruiker je bent ingelogd.", o: "Homedirectory", wit: true },
  { v: "Wat is een homedirectory?", a: "De persoonlijke werkdirectory van een gebruiker, waar hij (en alleen hij) toegang toe heeft. Linux is een multi-user systeem, dus elke gebruiker heeft er een.", o: "Homedirectory",
    uitleg: "Ingelogd als guest is je homedirectory /home/guest; als gebruiker joske is het /home/joske. Uitzondering: de homefolder van root is /root (werkcollege 3)." },
  { v: "Wat is de afkorting voor je homedirectory in een pad?", a: "~ (tilde)", o: "Homedirectory",
    uitleg: "Ingelogd als guest is /home/guest/doc hetzelfde als ~/doc." },
  { v: "Geef 3 manieren om vanuit /usr/src naar je homedirectory te gaan (gebruiker student).", a: "1. cd\n2. cd ~\n3. cd /home/student (absoluut) of cd ../../home/student (relatief)", o: "Homedirectory",
    uitleg: "In het oplossingendocument staat als derde manier 'cd ../../usr/src': dat brengt je terug naar /usr/src, niet naar je home. Juist is bv. cd ../../home/student." },
  { v: "Hoe vraag je op als welke gebruiker je bent ingelogd?", a: "$ whoami", o: "Homedirectory", oefening: true,
    uitleg: "Handig om je homedirectory te kennen: /home/ + je loginnaam." },
  { v: "Homedirectory van joske", a: "/home/joske", o: "Homedirectory" },
  { v: "/home/guest/doc is dus hetzelfde als ? met een tilde ?", a: "~/doc (als je als guest bent ingelogd).", o: "Homedirectory",
    uitleg: "~ staat telkens voor de homedirectory van de gebruiker die ingelogd is." },
  { v: "Hoeveel verborgen bestanden zitten er in je homedirectory?", a: "Zelf na te gaan met ls -a (de bestanden die met een punt beginnen).", o: "Homedirectory",
    uitleg: "Je kan ze tellen met ls -A | grep '^\\.' | wc -l (-A toont ze zonder . en ..)." },
  { v: "Toon alle bestanden in je homedirectory, ook de verborgen.", a: "$ ls -a ~", o: "Homedirectory", oefening: true,
    uitleg: "-a = all: ook de verborgen bestanden (die met een punt beginnen, bv. .bashrc)." },
  { v: "Maak in je homedirectory het bestand opdracht.txt.", a: "$ cd\n$ touch opdracht.txt", o: "Homedirectory", oefening: true,
    uitleg: "cd zonder argument brengt je naar je homedirectory; touch maakt een leeg bestand. Je kan het ook maken met vi opdracht.txt." },
  { v: "Wat is de homedirectory van gebruiker joske?", a: "/home/joske", o: "Homedirectory", examen: true,
    uitleg: "Gewone gebruikers krijgen een homedirectory onder /home, met hun gebruikersnaam: /home/joske.\nDaar bewaart de gebruiker zijn eigen bestanden en instellingen (verborgen bestanden die met een punt beginnen)." },
  { v: "Waarvoor staat ~ (tilde)?", a: "De homedirectory van de ingelogde gebruiker.", o: "Homedirectory", examen: true,
    uitleg: "~ is een afkorting voor de homedirectory van de gebruiker die nu ingelogd is.\nVoor student is ~ gelijk aan /home/student, voor root is ~ gelijk aan /root.\nVoorbeeld: cp bestand.txt ~ kopieert naar je homedirectory." },
  { v: "Je bent ingelogd als guest. Is /home/guest/doc hetzelfde als ~/doc?", a: "Ja.", o: "Homedirectory", examen: true,
    uitleg: "Als guest is je homedirectory /home/guest, dus ~ staat voor /home/guest.\n~/doc is dan hetzelfde als /home/guest/doc.\nAls een andere gebruiker ingelogd is, verwijst ~ naar diens homedirectory." },
  { v: "Wat is de homedirectory van root?", a: "/root", o: "Homedirectory", examen: true,
    uitleg: "root is de enige gebruiker waarvan de homedirectory niet onder /home staat, maar rechtstreeks onder de root: /root.\nZo blijft root kunnen inloggen, ook als /home op een aparte partitie staat die niet gemount is." },
  // ===== ls, wildcards en verborgen bestanden =====
  { v: "ls en verborgen bestanden (4.2 en 7)", a: "• ls toont de inhoud van een directory; met de optie -l zie je meer details: ls -l /usr/local/bin.\n• ls zonder opties of argumenten toont de huidige directory.\n• Let op het verschil tussen opties en argumenten.\n• Bestanden waarvan de naam met een '.' begint zijn verborgen; je ziet ze met ls -a.\n• Test ook: ls /etc/??[ae]* en ls /etc/n*", o: "ls, wildcards en verborgen bestanden", wit: true,
    uitleg: "Wildcards: * = eender welke tekens (ook geen), ? = precies 1 teken, [ae] = 1 teken dat a of e is." },
  { v: "Met welk commando vraag je de inhoud van een directory op, en wat doet de optie -l?", a: "ls (list). Met -l zie je meer details (rechten, eigenaar, grootte, datum, …).", o: "ls, wildcards en verborgen bestanden",
    uitleg: "ls zonder opties of argumenten toont de inhoud van de map waarin je je nu bevindt. Bv. ls -l /usr/local/bin toont de details van die map." },
  { v: "Welke bestanden zijn verborgen in Linux, en hoe zie je ze toch?", a: "Bestanden waarvan de naam met een punt begint (bv. .bashrc). Je ziet ze met ls -a.", o: "ls, wildcards en verborgen bestanden",
    uitleg: "-a = all. ls -al (= ls -a -l) toont een lange lijst mét verborgen bestanden. Op Ubuntu is ll vaak een afkorting (alias) voor ls -alF." },
  { v: "Geef 3 manieren om een verborgen bestand te maken.", a: "1. vi .verborgen\n2. vi starten en het bestand opslaan als .onzichtbaar\n3. Een bestaand bestand hernoemen: mv bestand .verdwenen", o: "ls, wildcards en verborgen bestanden",
    uitleg: "Het enige wat telt: de naam begint met een punt. Hernoemen doe je met mv ('verplaatsen met een andere naam')." },
  { v: "Wat toont ls /etc/n* ?", a: "Alle bestanden en mappen in /etc waarvan de naam met een n begint.", o: "ls, wildcards en verborgen bestanden",
    uitleg: "* is een wildcard: 'eender welke tekens, eender hoeveel (ook 0)'." },
  { v: "Wat toont ls /etc/??[ae]* ?", a: "Alle namen in /etc met eerst 2 willekeurige tekens, dan een a of een e, en daarna eender wat.", o: "ls, wildcards en verborgen bestanden",
    uitleg: "? = precies 1 willekeurig teken, [ae] = 1 teken dat a óf e is, * = eender welke tekens (ook geen). Voorbeeld: /etc/shadow matcht (s en h zijn de 2 willekeurige tekens, dan a, dan de rest). /etc/passwd matcht niet: het 3de teken is een s. Probeer het zelf op je VM." },
  { v: "ls -R", a: "ls -R toont recursief ook de inhoud van alle submappen.", o: "ls, wildcards en verborgen bestanden", extra: true,
    uitleg: "Uit je samenvatting, niet uit de cursus. Handig in combinatie met less: ls -R | less." },
  { v: "/home/guest/doc korter (als guest)", a: "~/doc", o: "ls, wildcards en verborgen bestanden" },
  { v: "Toon de inhoud van /usr/local/bin met details.", a: "$ ls -l /usr/local/bin", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Toon ook de verborgen bestanden.", a: "$ ls -a", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Toon alles in /etc dat met n begint.", a: "$ ls /etc/n*", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "* / ? / [ae]", a: "willekeurig veel tekens  /  precies 1 teken  /  a of e", o: "ls, wildcards en verborgen bestanden" },
  { v: "Sla in vi het bestand op als .onzichtbaar.", a: "$ vi\n  :w .onzichtbaar", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Verberg een bestaand bestand door het te hernoemen naar .verdwenen.", a: "$ mv bestand .verdwenen", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Als je ls zonder opties of argumenten uitvoert", a: "beeld je gewoon de inhoud af van de directory waarin je je op dat moment bevindt.", o: "ls, wildcards en verborgen bestanden",
    uitleg: "ls zonder argument = ls . (de huidige directory)." },
  { v: "Test ook: ls /etc/??[ae]* en ls /etc/n*", a: "ls /etc/??[ae]* toont alles in /etc waarvan het 3de teken een a of een e is. ls /etc/n* toont alles in /etc dat met n begint (bv. netplan, network, nanorc).", o: "ls, wildcards en verborgen bestanden",
    uitleg: "Jokertekens (wildcards): ? = precies één willekeurig teken, * = nul of meer willekeurige tekens, [ae] = precies één teken dat a of e is. Dus ??[ae]* = 2 willekeurige tekens, dan een a of e, dan om het even wat. Welke bestanden je ziet hangt af van je systeem: probeer het zelf." },
  { v: "Waarvoor dienen de commando's in hoofdstuk 7 vooral?", a: "Voor het bestandssysteem.", o: "ls, wildcards en verborgen bestanden",
    uitleg: "Kopiëren, verplaatsen en verwijderen van bestanden en directories." },
  { v: "Verwijder een directory met nog andere bestanden of directories erin.", a: "$ rm -r map", o: "ls, wildcards en verborgen bestanden", oefening: true,
    uitleg: "-r = recursief: de directory met alles erin. Vaak samen met -f (force, zonder vragen): rm -rf. Opgelet: er is geen prullenbak. Vind de optie zelf met man rm of rm --help." },
  { v: "Hoe weet je als welke gebruiker je ingelogd bent?", a: "$ whoami", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Zoek met de hulpcommando's hoe ls ook verborgen bestanden toont.", a: "$ man ls\n$ ls --help", o: "ls, wildcards en verborgen bestanden", oefening: true,
    uitleg: "De optie is -a (--all)." },
  { v: "Open vi zonder bestandsnaam en sla het bestand op als .onzichtbaar.", a: "$ vi\n  i\n  (typ je tekst)\n  ESC\n  :w .onzichtbaar\n  :q", o: "ls, wildcards en verborgen bestanden", oefening: true },
  { v: "Welke optie van ls toont meer details (rechten, eigenaar, grootte…)?", a: "-l", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "ls -l (long listing) toont per bestand:\nhet file type en de rechten (bv. -rwxr-xr-x)\nhet aantal hard links\nde eigenaar en de groep\nde grootte\nde datum van de laatste wijziging\nde naam" },
  { v: "Welke optie van ls toont ook verborgen bestanden?", a: "-a", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "-a = all. In Linux is een bestand verborgen als de naam met een punt begint, bv. .bashrc.\nGewone ls toont die niet, ls -a wel. Je ziet dan ook . (de huidige map) en .. (de ouderdirectory)." },
  { v: "Welke optie van ls toont groottes leesbaar (K, M, G)?", a: "-h", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "-h = human readable. In plaats van 4096 zie je 4.0K, in plaats van 1048576 zie je 1.0M.\n-h heeft enkel effect samen met -l, want enkel dan worden groottes getoond." },
  { v: "Geef het commando om alle bestanden, ook verborgen, met details en leesbare groottes in /etc te tonen.", a: "ls -hal /etc", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "-h = leesbare groottes, -a = ook verborgen bestanden, -l = details.\nOpties mag je samenvoegen achter één streepje: -hal. De volgorde van de letters maakt niet uit (-lah werkt ook).\n/etc is het argument: de map die je wil bekijken." },
  { v: "Hoe herken je een verborgen bestand in Linux?", a: "De naam begint met een punt, bv. .verborgen", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "Een bestand of map waarvan de naam met een punt begint, is verborgen: .bashrc, .profile, .ssh.\nEr bestaat geen apart attribuut voor verborgen, zoals in Windows. Om het te zien gebruik je ls -a." },
  { v: "Geef het commando om bestand tekst.txt te verbergen door het te hernoemen naar .verdwenen.", a: "mv tekst.txt .verdwenen", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "mv hernoemt (of verplaatst). Door de nieuwe naam met een punt te laten beginnen, wordt het bestand verborgen.\nHet bestand heet nu .verdwenen en verschijnt enkel nog met ls -a." },
  { v: "Wat toont ls /etc/n*?", a: "Alle bestanden en mappen in /etc die beginnen met n.", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "* is een wildcard voor 0 of meer willekeurige tekens.\nn* = alles wat begint met n, gevolgd door om het even wat: netplan, network, nsswitch.conf, …\nDe shell vult de wildcard in vóór ls uitgevoerd wordt." },
  { v: "Wat toont ls /etc/??[ae]*?", a: "Alles in /etc waarvan het derde teken een a of e is (eerst twee willekeurige tekens).", o: "ls, wildcards en verborgen bestanden", examen: true,
    uitleg: "? staat voor precies één willekeurig teken. ?? = de eerste twee tekens zijn willekeurig.\n[ae] staat voor precies één teken dat a of e moet zijn: dat is het derde teken.\n* = daarna om het even wat (ook niets).\nVoorbeelden die passen: /etc/shadow (derde teken a) en /etc/shells (derde teken e). /etc/passwd past niet (derde teken s)." },
  // ===== Mappen en bestanden beheren =====
  { v: "mkdir en rmdir (4.2 en 7)", a: "• mkdir naam: directory aanmaken\n• rmdir naam: lege directory verwijderen\n• Een directory met inhoud verwijderen vraagt een extra optie: zoek ze met de help-commando's.", o: "Mappen en bestanden beheren", wit: true },
  { v: "rm (4.2 en 7)", a: "rm bestand: bestand verwijderen.", o: "Mappen en bestanden beheren", wit: true,
    uitleg: "Er is geen prullenbak: wat je met rm verwijdert, is weg." },
  { v: "cp (4.2 en 7)", a: "cp bronbestand doelbestand: kopiëren, het bronbestand blijft bestaan. Bron en doel mogen ook een directory zijn: cp file1 /home/guest/", o: "Mappen en bestanden beheren", wit: true },
  { v: "mv (4.2 en 7)", a: "mv bronbestand doelbestand: verplaatsen (of hernoemen), het bronbestand verdwijnt.", o: "Mappen en bestanden beheren", wit: true },
  { v: "Met welke commando's maak je een directory, verwijder je een lege directory en verwijder je een bestand?", a: "mkdir naam: directory maken\nrmdir naam: lege directory verwijderen\nrm bestand: bestand verwijderen", o: "Mappen en bestanden beheren",
    uitleg: "Let op: rm verwijdert definitief, er is geen prullenbak!" },
  { v: "Hoe verwijder je een directory waar nog bestanden of mappen in zitten?", a: "$ rm -r map", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "rmdir werkt enkel op lege mappen. De optie vind je met rm --help of man rm." },
  { v: "Wat doet cp, en wat is de syntax?", a: "cp kopieert bestanden: cp bronbestand doelbestand. Het bronbestand blijft bestaan.", o: "Mappen en bestanden beheren",
    uitleg: "cp file1 file2 maakt een kopie file2. cp file1 /home/guest/ kopieert file1 naar de map /home/guest. Zowel bron als doel mogen een directory zijn." },
  { v: "Wat doet mv, en wat is het verschil met cp?", a: "mv verplaatst bestanden: mv bronbestand doelbestand. Het bronbestand verdwijnt. Met mv hernoem je ook bestanden.", o: "Mappen en bestanden beheren",
    uitleg: "cp = kopie (2 bestanden), mv = verplaatsen of hernoemen (1 bestand)." },
  { v: "Maak snel een leeg bestand bestand.txt.", a: "$ touch bestand.txt", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "In je extreme codesamenvatting staat 'ip bestand.txt': dat moet touch zijn." },
  { v: "Opdracht: maak opdracht.txt en een map opdracht, verplaats het bestand naar de map, kopieer het terug, verwijder de map en het originele bestand. Welke commando's?", a: "touch opdracht.txt\nmkdir opdracht\nmv opdracht.txt opdracht/\ncp opdracht/opdracht.txt .\nrm -r opdracht (of: rm opdracht/opdracht.txt en rmdir opdracht)\nrm opdracht.txt", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "touch = een leeg bestand maken. mkdir = een map maken. mv = verplaatsen. cp = kopiëren; de . betekent 'naar de huidige map'. rm -r = een map met inhoud verwijderen (-r = recursief). rmdir = een lege map verwijderen. rm = een bestand verwijderen. Het oplossingendocument gebruikt cp in plaats van mv bij de eerste stap; volgens de opdracht moet je verplaatsen (mv)." },
  { v: "Maak een map met de naam map.", a: "$ mkdir map", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Verwijder het bestand bestand.", a: "$ rm bestand", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Kopieer file1 naar file2.", a: "$ cp file1 file2", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Verplaats een bestand (het bronbestand verdwijnt).", a: "$ mv bronbestand doelbestand", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Bash kent tab-completion, typ eens cd /ho en druk daarna op <tab>", a: "systeem zal zelf het commando omzetten naar: cd /home", o: "Mappen en bestanden beheren",
    uitleg: "Tab-completion werkt voor commando's, directories en bestanden." },
  { v: "Waarop moet je letten bij de opties van ls?", a: "Op het verschil tussen opties en argumenten.", o: "Mappen en bestanden beheren",
    uitleg: "In ls -l /usr/local/bin is -l de optie (hoe: met details) en /usr/local/bin het argument (waarvan)." },
  { v: "Aanmaken van directories", a: "mkdir met als argument de naam van de nieuwe directory die je wilt aanmaken", o: "Mappen en bestanden beheren",
    uitleg: "Bv. mkdir opdracht. Met mkdir -p a/b/c maak je meteen alle tussenliggende directories." },
  { v: "Lege directories verwijderen", a: "rmdir", o: "Mappen en bestanden beheren",
    uitleg: "rmdir weigert als de directory niet leeg is. Een niet-lege directory verwijder je met rm -r (zie verder)." },
  { v: "Ga naar /usr/src.", a: "$ cd /usr/src", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Typ cd /ho en vul aan zonder verder te typen.", a: "$ cd /ho\n  Tab", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "Bash vult aan tot cd /home." },
  { v: "Toon alles in /etc waarvan de derde letter a of e is.", a: "$ ls /etc/??[ae]*", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "? = precies 1 teken, [ae] = a of e, * = de rest." },
  { v: "Kopieer file1 naar file2. Bestaat file1 daarna nog?", a: "$ cp file1 file2", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "Ja, file1 blijft bestaan." },
  { v: "Kopieer file1 naar de directory /home/guest.", a: "$ cp file1 /home/guest/", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Verplaats opdracht.txt naar de directory opdracht.", a: "$ mv opdracht.txt opdracht/", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Kopieer het bestand terug naar je homedirectory.", a: "$ cp opdracht/opdracht.txt .", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "De . betekent 'naar de huidige map'." },
  { v: "Probeer de directory opdracht te verwijderen met rmdir. Wat gebeurt er?", a: "$ rmdir opdracht\n  rmdir: failed to remove 'opdracht': Directory not empty", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "Het mislukt: rmdir werkt enkel op lege mappen." },
  { v: "Zoek met de hulpcommando's de optie om een niet-lege map te verwijderen en verwijder opdracht.", a: "$ rm --help\n$ rm -r opdracht", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "De optie is -r (recursief)." },
  { v: "Kopieer file1 naar de directory /home/guest en controleer of het daar staat.", a: "$ cp file1 /home/guest/\n$ ls /home/guest", o: "Mappen en bestanden beheren", oefening: true },
  { v: "Hernoem tekst.txt naar notities.txt.", a: "$ mv tekst.txt notities.txt", o: "Mappen en bestanden beheren", oefening: true,
    uitleg: "Hernoemen doe je met mv: 'verplaatsen met een andere naam'." },
  { v: "Welk commando maakt een directory aan? Geef het commando voor de directory opdracht.", a: "mkdir opdracht", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "mkdir = make directory. mkdir opdracht maakt de map opdracht in de huidige directory.\nMet een pad kan je ze ook ergens anders maken: mkdir /tmp/opdracht.\nMet -p maak je meteen ook de tussenliggende mappen: mkdir -p a/b/c." },
  { v: "Welk commando verwijdert een lege directory?", a: "rmdir", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "rmdir = remove directory. Het werkt enkel als de map leeg is.\nZitten er nog bestanden in, dan krijg je een foutmelding (Directory not empty). Dan gebruik je rm -r." },
  { v: "Welk commando verwijdert een bestand?", a: "rm", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "rm = remove. rm bestand.txt verwijdert het bestand.\nLet op: in de CLI is er geen prullenbak. Wat verwijderd is, is weg.\nMet -i vraagt rm eerst om bevestiging." },
  { v: "Geef het commando om de directory opdracht te verwijderen, inclusief alle bestanden erin.", a: "rm -r opdracht", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "-r = recursief: rm verwijdert de map en alles wat erin zit, ook submappen.\nWees voorzichtig: er is geen prullenbak.\nrm -rf verwijdert ook zonder vragen (f = force)." },
  { v: "Hoe maak je een leeg bestand aan (één mogelijkheid)?", a: "touch bestand.txt (of via vi, nano, echo)", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "touch maakt een leeg bestand als het nog niet bestaat. Bestaat het al, dan past touch enkel de datum van de laatste wijziging aan.\nAndere manieren: echo tekst > bestand.txt, of een editor zoals vi of nano openen en opslaan." },
  { v: "Geef de syntax van cp.", a: "cp bronbestand doelbestand (of cp SOURCE... DIRECTORY)", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "cp = copy.\ncp bronbestand doelbestand: een kopie met een (nieuwe) naam.\ncp bronbestand map/: een kopie in een andere map, met dezelfde naam.\nMet -r kopieer je een hele map: cp -r map1 map2." },
  { v: "Kopieer /etc/fstab naar /temp/student/. Je working directory is /etc.", a: "cp fstab /temp/student/", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "Je staat in /etc, dus fstab is een relatief pad naar /etc/fstab.\nHet doel /temp/student/ is een absoluut pad naar een map. Het bestand komt daar terecht met dezelfde naam fstab." },
  { v: "Kopieer /etc/fstab naar /temp/student/ met een absoluut pad, vanuit eender welke directory.", a: "cp /etc/fstab /temp/student/", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "Met absolute paden voor de bron (/etc/fstab) én het doel (/temp/student/) maakt het niet uit in welke map je staat.\nAbsolute paden beginnen altijd met /." },
  { v: "Wat doet cp file1 file2?", a: "Kopieert file1 naar file2; file1 blijft bestaan.", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "cp file1 file2 maakt een kopie van file1 met de naam file2.\nfile1 blijft ongewijzigd bestaan. Bestaat file2 al, dan wordt het overschreven, zonder te vragen." },
  { v: "Wat doet cp file1 /home/guest/?", a: "Kopieert file1 naar de directory /home/guest.", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "Als het doel een bestaande map is, komt de kopie in die map terecht met dezelfde naam: /home/guest/file1.\nDe slash achteraan maakt duidelijk dat het om een map gaat." },
  { v: "Wat is het verschil tussen cp en mv?", a: "cp kopieert (bron blijft bestaan). mv verplaatst (bron verdwijnt). mv gebruik je ook om te hernoemen.", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "cp: na afloop bestaan er twee exemplaren.\nmv: na afloop bestaat er één exemplaar, op de nieuwe plaats of met de nieuwe naam.\nIn Linux bestaat er geen apart rename-commando: hernoemen doe je met mv oud nieuw." },
  { v: "Verplaats opdracht.txt naar de subdirectory opdracht.", a: "mv opdracht.txt opdracht/", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "mv verplaatst het bestand naar de map opdracht (een relatief pad vanuit de huidige map).\nDe slash achteraan maakt duidelijk dat opdracht een map is. Het bestand heet daarna opdracht/opdracht.txt." },
  { v: "Kopieer opdracht/opdracht.txt terug naar de huidige directory.", a: "cp opdracht/opdracht.txt .", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "De bron is opdracht/opdracht.txt (een relatief pad).\nHet doel is . : de huidige directory.\nNa afloop staat het bestand twee keer: in de submap en in de huidige map." },
  { v: "Hernoem oud.txt naar nieuw.txt.", a: "mv oud.txt nieuw.txt", o: "Mappen en bestanden beheren", examen: true,
    uitleg: "mv met een nieuwe naam in dezelfde map is hernoemen. oud.txt bestaat daarna niet meer, nieuw.txt wel.\nBestaat nieuw.txt al, dan wordt het overschreven." },
  // ===== Teksteditors vi en nano =====
  { v: "De teksteditor vi (5)", a: "• Zoals Windows Notepad heeft Linux teksteditors. vi is zeer geavanceerd, maar even wennen.\n• vi start in commando mode: je kan niet meteen tikken.\n• i = insert mode, a = append mode (verschil: positie van de cursor t.o.v. het teken).\n• ESC: terug naar commando mode.", o: "Teksteditors vi en nano", wit: true },
  { v: "vi-commando's (5)", a: "Vanbuiten kennen:", o: "Teksteditors vi en nano", wit: true,
    uitleg: "Good-to-know: dd = regel verwijderen, yy = regel kopiëren, 5yy = 5 regels kopiëren, p = plakken, /zoektekst = zoeken, n = volgende.",
    tabel: [
      ["Commando", "Actie"],
      [":w", "sla het bestand op"],
      [":w file.txt", "sla op als file.txt"],
      [":wq", "sla op en verlaat vi"],
      [":q!", "verlaat vi zonder op te slaan"]
    ] },
  { v: "De teksteditor nano (5)", a: "• Een andere zeer populaire teksteditor, iets gebruiksvriendelijker dan vi.\n• Niet in alle distributies voorzien (vi wel).\n• Handig: de balk onderaan met de belangrijkste opties, bv. Ctrl-O (write out) om op te slaan.", o: "Teksteditors vi en nano", wit: true,
    uitleg: "^ in de balk betekent Ctrl. Afsluiten met Ctrl-X." },
  { v: "In welke mode start vi op, en hoe begin je te typen?", a: "vi start in commando mode: je kan niet meteen typen. Met i ga je naar insert mode, met a naar append mode.", o: "Teksteditors vi en nano",
    uitleg: "Het verschil tussen i en a is de positie van de cursor t.o.v. het teken: i voegt in vóór de cursor, a erna." },
  { v: "Hoe ga je in vi terug naar commando mode?", a: "Met ESC.", o: "Teksteditors vi en nano",
    uitleg: "Pas in commando mode kan je opslaan, afsluiten, regels kopiëren, …" },
  { v: "Hoe zoek je in vi naar een woord?", a: "/zoektekst. Met n spring je naar de volgende plaats waar het woord voorkomt.", o: "Teksteditors vi en nano",
    uitleg: "Dezelfde manier van zoeken werkt in less en in man-pages." },
  { v: "Wat is nano, en hoe sla je er een bestand mee op?", a: "Een andere populaire teksteditor, gebruiksvriendelijker dan vi, maar niet in alle distributies voorzien. Opslaan: Ctrl+O (write out). Afsluiten: Ctrl+X.", o: "Teksteditors vi en nano",
    uitleg: "Onderaan in nano staat een balk met de belangrijkste opties; ^ betekent Ctrl." },
  { v: "Je hebt in vi per ongeluk tekst verknoeid en wil afsluiten zonder op te slaan. Wat typ je?\na) :wq\nb) :w\nc) :q!\nd) Ctrl+X", a: "c) :q!", o: "Teksteditors vi en nano",
    uitleg: "Eerst ESC om zeker in commando mode te zitten, dan :q! . a) en b) slaan de fouten net op; d) is afsluiten in nano." },
  { v: "Open tekst.txt in vi.", a: "$ vi tekst.txt", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "Bestaat tekst.txt nog niet, dan maakt vi het aan zodra je opslaat." },
  { v: "Hoe ga je in vi naar insert mode, en hoe naar append mode?", a: "Insert mode: i\nAppend mode: a", o: "Teksteditors vi en nano",
    uitleg: "Bij i typ je vóór het teken onder de cursor, bij a erna. Met ESC ga je terug naar commando mode." },
  { v: "Sla in vi het bestand op.", a: "  ESC\n  :w", o: "Teksteditors vi en nano", oefening: true,
    uitleg: ":w komt van 'write'. Deze moet je volgens de cursus vanbuiten kennen." },
  { v: "Sla in vi het bestand op als file.txt.", a: "  :w file.txt", o: "Teksteditors vi en nano", oefening: true },
  { v: "Sla op en verlaat vi in één keer.", a: "  :wq", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "Vanbuiten kennen!" },
  { v: "Verlaat vi zonder de wijzigingen op te slaan.", a: "  :q!", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "Het ! betekent 'forceer': vi sluit af, ook al zijn er niet-opgeslagen wijzigingen. Vanbuiten kennen!" },
  { v: "Verwijder in vi de regel waar je cursor staat.", a: "  dd", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "In commando mode (na ESC)." },
  { v: "Kopieer in vi de huidige regel.", a: "  yy", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "yy komt van 'yank', het vi-woord voor kopiëren." },
  { v: "Kopieer in vi 5 regels vanaf de cursor.", a: "  5yy", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "Het getal ervoor zegt hoeveel regels: 5yy = 5 regels kopiëren vanaf de huidige." },
  { v: "Plak in vi de gekopieerde regels.", a: "  p", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "p = paste." },
  { v: "Zoek in vi naar zoektekst en spring naar de volgende plek.", a: "  /zoektekst\n  n", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "Dezelfde manier van zoeken werkt in less en in man-pages." },
  { v: "Sluit nano af.", a: "  Ctrl + X", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "In de balk onderaan nano staat ^X: ^ betekent Ctrl." },
  { v: "Wat is de Linux-tegenhanger van Windows Notepad?", a: "Teksteditors zoals vi en nano.", o: "Teksteditors vi en nano",
    uitleg: "Een teksteditor bewerkt platte tekst (zonder opmaak), ideaal voor configuratiebestanden en scripts." },
  { v: "Hoe omschrijft de cursus vi?", a: "Een zeer geavanceerde teksteditor, maar in het begin is het even wennen.", o: "Teksteditors vi en nano",
    uitleg: "Vandaag gebruik je meestal vim (vi improved), dat via het commando vi opstart." },
  { v: "Hoe kan je beginnen typen ?", a: "commando i in kom je in insert mode waarin je tekst kan intikken of a voor het de\nappend mode. Het verschil zit hem in de positie van de cursor t.o.v. het character dat je typt.", o: "Teksteditors vi en nano",
    uitleg: "i = insert (tekst invoegen vóór de cursor), a = append (tekst toevoegen ná de cursor)." },
  { v: "Kan je in vi meteen beginnen typen na het opstarten?", a: "Nee: je komt terecht in commando mode, dus je kan niet direct beginnen tikken.", o: "Teksteditors vi en nano",
    uitleg: "Druk eerst i (insert) of a (append)." },
  { v: "Hoe kom je in append mode? Wat is het verschil met insert mode?", a: "a · bij a typ je ná het teken onder de cursor, bij i ervoor.", o: "Teksteditors vi en nano" },
  { v: "Sla in nano een bestand op.", a: "  Ctrl + O\n  Enter", o: "Teksteditors vi en nano", oefening: true,
    uitleg: "O van 'write out'. Je ziet het ook in de balk onderaan (^O)." },
  { v: "Wat is een voor- en een nadeel van nano tegenover vi?", a: "Voordeel: gebruiksvriendelijker, met een balk met opties onderaan. Nadeel: niet in elke distributie aanwezig (vi wel).", o: "Teksteditors vi en nano" },
  { v: "Open tekst.txt in nano.", a: "$ nano tekst.txt", o: "Teksteditors vi en nano", oefening: true },
  { v: "In welke modus start vi?", a: "Commando-modus (je kan niet meteen typen).", o: "Teksteditors vi en nano", examen: true,
    uitleg: "vi start in de commando-modus (normal mode). Wat je typt, wordt gezien als commando, niet als tekst.\nOm tekst te typen ga je naar insert mode met i of a. Met ESC kom je terug in de commando-modus." },
  { v: "Met welke toets ga je in vi naar insert mode? En append mode?", a: "i = insert, a = append (verschil: positie van de cursor t.o.v. het teken).", o: "Teksteditors vi en nano", examen: true,
    uitleg: "i (insert): je begint te typen vóór het teken waar de cursor staat.\na (append): je begint te typen na het teken waar de cursor staat.\nIn beide gevallen zie je onderaan -- INSERT --. Met ESC ga je terug naar de commando-modus." },
  { v: "Hoe ga je in vi terug naar commando-modus?", a: "ESC", o: "Teksteditors vi en nano", examen: true,
    uitleg: "Met ESC verlaat je insert mode en ben je terug in de commando-modus. Daar kan je commando's geven zoals :w (opslaan), :q (afsluiten), dd (regel verwijderen).\nTwijfel je in welke modus je zit, druk dan gewoon op ESC." },
  { v: "Hoe sla je een bestand op in vi?", a: ":w", o: "Teksteditors vi en nano", examen: true,
    uitleg: "In de commando-modus typ je : (dubbelpunt). Onderaan verschijnt een commandoregel. w = write: het bestand wordt opgeslagen onder de huidige naam.\nJe moet eerst met ESC uit insert mode." },
  { v: "Hoe sla je op als file.txt in vi?", a: ":w file.txt", o: "Teksteditors vi en nano", examen: true,
    uitleg: ":w gevolgd door een bestandsnaam slaat de inhoud op onder die naam.\nHandig als je vi geopend hebt zonder bestandsnaam, of als je een kopie wil bewaren." },
  { v: "Hoe sla je op en verlaat je vi?", a: ":wq", o: "Teksteditors vi en nano", examen: true,
    uitleg: ":wq = write en quit: opslaan en vi afsluiten in één keer.\n:x en ZZ doen hetzelfde." },
  { v: "Hoe verlaat je vi zonder de wijzigingen op te slaan?", a: ":q!", o: "Teksteditors vi en nano", examen: true,
    uitleg: ":q! = quit zonder opslaan. Het uitroepteken forceert het afsluiten, ook als er niet-opgeslagen wijzigingen zijn.\nZonder ! weigert vi af te sluiten als je iets gewijzigd hebt (No write since last change)." },
  { v: "Wat doet dd in vi?", a: "De lijn waar de cursor staat verwijderen.", o: "Teksteditors vi en nano", examen: true,
    uitleg: "dd verwijdert de volledige regel waarop de cursor staat (in de commando-modus).\n5dd verwijdert 5 regels vanaf de huidige.\nDe verwijderde regel kan je daarna plakken met p." },
  { v: "Wat doet yy in vi? En 5yy?", a: "yy kopieert de huidige regel; 5yy kopieert 5 regels vanaf de huidige.", o: "Teksteditors vi en nano", examen: true,
    uitleg: "yy (yank) kopieert de volledige regel waarop de cursor staat.\nMet een getal ervoor kopieer je meerdere regels: 5yy kopieert de huidige regel en de 4 regels eronder.\nPlakken doe je met p." },
  { v: "Wat doet p in vi?", a: "Plakken (paste) van de gekopieerde regels.", o: "Teksteditors vi en nano", examen: true,
    uitleg: "p (paste) plakt wat je gekopieerd (yy) of verwijderd (dd) hebt, onder de regel waar de cursor staat.\nP (hoofdletter) plakt boven de huidige regel." },
  { v: "Hoe zoek je het woord zoektekst in vi, en hoe spring je naar de volgende?", a: "/zoektekst, daarna n voor de volgende plaats.", o: "Teksteditors vi en nano", examen: true,
    uitleg: "In de commando-modus typ je / gevolgd door de zoektekst en druk je op Enter: /zoektekst.\nn springt naar de volgende plaats waar de tekst voorkomt, N naar de vorige." },
  { v: "Welke andere, gebruiksvriendelijkere teksteditor wordt vermeld?", a: "nano", o: "Teksteditors vi en nano", examen: true,
    uitleg: "nano is eenvoudiger dan vi: je kan meteen typen en onderaan staan de belangrijkste sneltoetsen.\nHet ^-teken in die lijst betekent Ctrl: ^O = Ctrl+O (opslaan), ^X = Ctrl+X (afsluiten)." },
  { v: "Hoe sla je op in nano?", a: "CTRL-O (write out)", o: "Teksteditors vi en nano", examen: true,
    uitleg: "Ctrl+O = write out: nano vraagt de bestandsnaam en je bevestigt met Enter.\nCtrl+X sluit nano af. Zijn er niet-opgeslagen wijzigingen, dan vraagt nano eerst of je wil opslaan." },
  { v: "Waar of niet waar: nano is net als vi in alle distributies voorzien.", a: "Niet waar. vi zit in alle distributies, nano niet.", o: "Teksteditors vi en nano", examen: true,
    uitleg: "vi (of vim) zit in alle Linuxdistributies en Unix-systemen. Daarom is het belangrijk om vi te kennen: op een minimale server is het soms de enige editor.\nnano is gebruiksvriendelijker, maar niet altijd geïnstalleerd." },
  { v: "Open het bestand .verborgen in vi.", a: "vi .verborgen", o: "Teksteditors vi en nano", examen: true,
    uitleg: "vi gevolgd door de bestandsnaam opent dat bestand. Een verborgen bestand opent op dezelfde manier: de punt hoort gewoon bij de naam.\nBestaat het bestand nog niet, dan maakt vi het aan bij het opslaan." },
  // ===== Toegangsrechten =====
  { v: "Toegangsrechten (6)", a: "• 3 soorten gebruikers: de eigenaar (user, u), de groepsgenoten (group, g) en de andere gebruikers (others, o).\n• Elk kan 3 rechten hebben op een bestand of map: lezen (r), schrijven (w) en uitvoeren (x).\n• Je ziet ze met ls -l.\n• Voorbeeld: -rwxr-xr-x → user rwx, group r-x, others r-x. De groep en de anderen mogen lezen en uitvoeren, niet wijzigen.", o: "Toegangsrechten", wit: true },
  { v: "Rechten wijzigen met chmod (6)", a: "• chmod + het recht dat je wil wijzigen + de bestandsnaam.\n• Numeriek: r = 4, w = 2, x = 1; per groep optellen. -rwxr-xr-x = chmod 755 bestand.\n• Met letters: u, g, o en + of -. chmod u-w,g+w,o+w bestand neemt het schrijfrecht af van de eigenaar en geeft het aan de groep en de anderen.", o: "Toegangsrechten", wit: true,
    uitleg: "De getallen komen overeen met de binaire waarde van de positie: r = 100, w = 010, x = 001.",
    tabel: [
      ["", "r", "w", "x"],
      ["4 (r)", "1", "0", "0"],
      ["2 (w)", "0", "1", "0"],
      ["1 (x)", "0", "0", "1"]
    ] },
  { v: "Welke 3 soorten gebruikers hebben toegangsrechten op een bestand, en welke 3 rechten zijn er?", a: "Gebruikers: de eigenaar (user, u), de groepsgenoten van de eigenaar (group, g) en de andere gebruikers (others, o).\nRechten: lezen (read, r), schrijven (write, w) en uitvoeren (execute, x).", o: "Toegangsrechten",
    uitleg: "Je ziet ze met ls -l. Bij een map betekent x: de map mogen binnengaan (cd)." },
  { v: "Wat betekenen 1, 2 en 3 in deze rechten -rwxr-xr-x?", a: "1. user (de eigenaar): rwx\n2. group (groepsgenoten): r-x\n3. others (andere gebruikers): r-x", o: "Toegangsrechten", img: "afbeeldingen/DesktopOS_linux_wc1/lx_rechten_vraag.png", imgAntwoord: "afbeeldingen/DesktopOS_linux_wc1/lx_rechten.png",
    uitleg: "Het eerste teken (-) is het bestandstype. De eigenaar mag alles: lezen, schrijven en uitvoeren. De groep en de anderen mogen enkel lezen en uitvoeren, niet wijzigen: daarom het streepje waar anders de w zou staan." },
  { v: "Benoem 1 tot 5 in deze uitvoer van ls -l.", a: "1. rights (de rechten)\n2. owner (de eigenaar)\n3. group owner (de groep)\n4. file type (bestandstype)\n5. other users (de rechten van de andere gebruikers)", o: "Toegangsrechten", img: "afbeeldingen/DesktopOS_linux_wc1/lx_lsl_vraag.png", imgAntwoord: "afbeeldingen/DesktopOS_linux_wc1/lx_lsl.png",
    uitleg: "Bestandstypes: - = gewoon bestand (regular file), d = directory, l = link. In -rwxrwxr-x: user rwx, group rwx, others r-x. Het getal 1 is het aantal hardlinks, 1735 de grootte in bytes, dan datum/tijd en naam." },
  { v: "Wat betekent het eerste teken van -rwxr-xr-x, d rwxr-xr-x en lrwxrwxrwx?", a: "- = gewoon bestand (regular file)\nd = directory\nl = link", o: "Toegangsrechten",
    uitleg: "Dat eerste teken is het bestandstype, de volgende 9 tekens zijn de rechten (3 x 3)." },
  { v: "Welke 7 kolommen toont ls -l per bestand?", a: "1. type + rechten\n2. aantal (hard)links\n3. eigenaar\n4. groep\n5. grootte (bytes)\n6. datum/tijd van laatste wijziging\n7. naam", o: "Toegangsrechten",
    uitleg: "Voorbeeld: drwxr-xr-x 12 root root 4096 Sep 2 06:08 map. Bij een map is de grootte meestal 4096." },
  { v: "Met welk commando wijzig je de toegangsrechten van een bestand?", a: "chmod (change mode).", o: "Toegangsrechten",
    uitleg: "Als argumenten geef je het recht dat je wil wijzigen en de bestandsnaam. Dat kan op 2 manieren: met cijfers (numeriek) of met letters en + / -." },
  { v: "Vul de tabel aan: welke binaire waarde (r w x) hoort bij 4, 2 en 1?", a: "4 → 1 0 0 (r)\n2 → 0 1 0 (w)\n1 → 0 0 1 (x)", o: "Toegangsrechten", img: "afbeeldingen/DesktopOS_linux_wc1/lx_chmod_tabel_vraag.png", imgAntwoord: "afbeeldingen/DesktopOS_linux_wc1/lx_chmod_tabel.png",
    uitleg: "De getallen komen overeen met de binaire waarde van de positie: r is de linkse bit (4), w de middelste (2), x de rechtse (1). Per groep tel je ze op: rwx = 4+2+1 = 7, r-x = 4+1 = 5, r-- = 4, --- = 0." },
  { v: "Maak met de numerieke methode -rwxr-xr-x van een bestand.", a: "$ chmod 755 bestand", o: "Toegangsrechten", oefening: true,
    uitleg: "user rwx = 4+2+1 = 7; group r-x = 4+0+1 = 5; others r-x = 5." },
  { v: "Wat betekenen de cijfers 7, 6, 5, 4 en 0 bij chmod?", a: "7 = rwx\n6 = rw-\n5 = r-x\n4 = r--\n0 = ---", o: "Toegangsrechten",
    uitleg: "r = 4, w = 2, x = 1. 3 = -wx en 2 = -w- komen weinig voor." },
  { v: "Welke rechten geeft chmod 640 bestand?", a: "-rw-r-----", o: "Toegangsrechten",
    uitleg: "user 6 = rw-, group 4 = r--, others 0 = ---. De eigenaar mag lezen en schrijven, de groep enkel lezen, de anderen niets." },
  { v: "Wat doet chmod u-w,g+w,o+w bestand?", a: "Het neemt het schrijfrecht af van de eigenaar (u-w), en geeft schrijfrecht aan de groep (g+w) en aan de andere gebruikers (o+w).", o: "Toegangsrechten",
    uitleg: "u = user, g = group, o = other; + = recht geven, - = recht afnemen. Let op: geen spaties na de komma's!" },
  { v: "De rechten van tekst.txt moeten -rwxr-xr-- worden. Geef de 2 manieren.", a: "$ chmod 754 tekst.txt\n$ chmod u=rwx,g=rx,o=r tekst.txt", o: "Toegangsrechten", oefening: true,
    uitleg: "Numeriek of met letters. 7 = rwx, 5 = r-x, 4 = r--. Controleer daarna met ls -l. Vanuit -rw-rw-r-- kan ook: chmod u+x,g-w,g+x tekst.txt." },
  { v: "Wat deed het chmod-commando in deze terminal met de rechten van tekst.txt?", a: "chmod 754 tekst.txt veranderde -rw-rw-r-- in -rwxr-xr--: de eigenaar krijgt er x bij, de groep verliest w en krijgt x, others blijft r--.", o: "Toegangsrechten", img: "afbeeldingen/DesktopOS_linux_wc1/lx_opl1.png",
    uitleg: "754: 7 = rwx (user), 5 = r-x (group), 4 = r-- (others). Met ls -l voor en na zie je het verschil." },
  { v: "Lees dit commando: chmod u+x,g-w,g+x,o-x tekst.txt. Wat betekent elk deel?", a: "u+x: user krijgt execute\ng-w: group verliest write\ng+x: group krijgt execute\no-x: others verliest execute", o: "Toegangsrechten", img: "afbeeldingen/DesktopOS_linux_wc1/lx_opl2.png",
    uitleg: "Resultaat: -rwxr-xr-- (zie ls -l). Dit is de 'letters'-manier om hetzelfde te bereiken als chmod 754." },
  { v: "Juist of fout? Met chmod 777 mag iedereen een bestand lezen, wijzigen en uitvoeren.", a: "JUIST", o: "Toegangsrechten",
    uitleg: "777 = rwxrwxrwx: user, group en others hebben alle rechten. Dat is meestal een slecht idee voor de veiligheid." },
  { v: "Juist of fout? Bij chmod met letters mag je spaties zetten na de komma's: chmod u-w, g+w bestand.", a: "FOUT", o: "Toegangsrechten",
    uitleg: "Zonder spaties: chmod u-w,g+w bestand. Een spatie maakt van 'g+w' een apart argument, en dan denkt chmod dat het een bestandsnaam is." },
  { v: "Bekijk de rechten van tekst.txt.", a: "$ ls -l tekst.txt", o: "Toegangsrechten", oefening: true },
  { v: "Eerste teken bij ls -l: bestand / map / link", a: "-  /  d  /  l", o: "Toegangsrechten" },
  { v: "Betekenis -rwxr-xr-x", a: "user rwx  ·  group r-x  ·  others r-x", o: "Toegangsrechten" },
  { v: "Geef tekst.txt de rechten -rwxr-xr-- met letters.", a: "$ chmod u=rwx,g=rx,o=r tekst.txt", o: "Toegangsrechten", oefening: true },
  { v: "Lees de regel -rwxrwxr-x 1 piet project 1735 Mar 13 20:36 main.c.", a: "-rwxrwxr-x = rechten (gewoon bestand; owner rwx, group rwx, other r-x), 1 = aantal links, piet = owner, project = group owner, 1735 = grootte in bytes, Mar 13 20:36 = datum en tijd van de laatste wijziging, main.c = bestandsnaam.", o: "Toegangsrechten",
    uitleg: "Dit is de uitvoer van ls -l /usr/project1/. main.c is een bestand met programmacode in C." },
  { v: "Waarmee wijzig je rechten?", a: "Via chmod.", o: "Toegangsrechten",
    uitleg: "chmod = change mode." },
  { v: "Waar staan r, w en x voor?", a: "r = read, w = write, x = execute.", o: "Toegangsrechten",
    uitleg: "Lezen, schrijven (wijzigen) en uitvoeren (als programma starten)." },
  { v: "Hoe werkt de numerieke methode van chmod?", a: "4 staat voor r, 2 staat voor w, 1 staat voor x (binair: r = 100, w = 010, x = 001). Per groep (user, group, other) tel je de waarden op.", o: "Toegangsrechten",
    uitleg: "rwx = 4+2+1 = 7, r-x = 4+1 = 5, rw- = 6, r-- = 4." },
  { v: "Welk getal geeft rw-r--r-- en welk rwx------?", a: "rw-r--r-- = 644 (6 = 4+2, 4, 4); rwx------ = 700.", o: "Toegangsrechten",
    uitleg: "Eigen oefening: 644 is typisch voor gewone bestanden, 700 voor een privé-map of -script." },
  { v: "Hebben toegangsrechten enkel betrekking op bestanden?", a: "Nee: ieder van de 3 (u, g, o) kan 3 rechten hebben op een bestand of een map.", o: "Toegangsrechten",
    uitleg: "Voor een map: r = inhoud tonen, w = bestanden aanmaken/verwijderen, x = de map binnengaan." },
  { v: "Waarom zijn de getallen bij chmod 4, 2 en 1?", a: "Ze komen overeen met de binaire waarde van de positie: r = 100, w = 010, x = 001. Je kan ze per groep (u, g of o) optellen als binaire getallen.", o: "Toegangsrechten",
    uitleg: "rwx = 111 binair = 7, r-x = 101 = 5, r-- = 100 = 4." },
  { v: "Leg uit wat -rwxr-xr-x betekent.", a: "- = gewoon bestand · user rwx (alles) · group r-x · others r-x (lezen en uitvoeren, niet wijzigen)", o: "Toegangsrechten" },
  { v: "Neem het schrijfrecht af van de eigenaar en geef de groep en de anderen schrijfrecht op bestand.", a: "$ chmod u-w,g+w,o+w bestand", o: "Toegangsrechten", oefening: true,
    uitleg: "Geen spaties na de komma's." },
  { v: "Geef tekst.txt de rechten -rwxr-xr-- met de numerieke methode en controleer.", a: "$ chmod 754 tekst.txt\n$ ls -l tekst.txt", o: "Toegangsrechten", oefening: true,
    uitleg: "7 = rwx, 5 = r-x, 4 = r--." },
  { v: "Welke drie soorten gebruikers hebben rechten op een bestand?", a: "user/owner (u), group (g) en other (o).", o: "Toegangsrechten", examen: true,
    uitleg: "u = user: de eigenaar (owner) van het bestand.\ng = group: de groep van het bestand.\no = other: alle andere gebruikers.\na = all: alle drie samen (gebruik je bij de lettermethode van chmod).\nIn ls -l zie je ze in die volgorde: rwx rwx rwx." },
  { v: "Welke drie rechten bestaan er?", a: "read (r), write (w), execute (x).", o: "Toegangsrechten", examen: true,
    uitleg: "r = read: lezen (bij een map: de inhoud tonen met ls).\nw = write: wijzigen (bij een map: bestanden aanmaken en verwijderen).\nx = execute: uitvoeren als programma (bij een map: erin gaan met cd)." },
  { v: "Wat betekent het eerste teken in -rwxrwxr-x? Welke waarden kan het hebben?", a: "Het file type: - = regular file, d = directory, l = link.", o: "Toegangsrechten", examen: true,
    uitleg: "Het eerste teken van ls -l is het file type:\n- = gewoon bestand (regular file)\nd = directory\nl = (symbolic) link\nDaarna volgen 9 tekens: 3 voor de user, 3 voor de group, 3 voor other." },
  { v: "Gegeven:\ndrwxr-xr-x 2 root root 4.0K Aug 7 10:44 grub.d\n\nWelke rechten heeft other op grub.d?\n\n1: geen\n2: enkel lezen\n3: enkel schrijven\n4: enkel uitvoeren\n5: lezen en schrijven\n6: lezen en uitvoeren\n7: schrijven en uitvoeren\n8: lezen, schrijven en uitvoeren", a: "6: lezen en uitvoeren (r-x)", o: "Toegangsrechten", examen: true,
    uitleg: "Je leest drwxr-xr-x van links naar rechts:\nd = file type: een directory.\nrwx = rechten van de owner (root): lezen, schrijven, uitvoeren.\nr-x = rechten van de group (root): lezen en uitvoeren.\nr-x = rechten van other (alle anderen): lezen en uitvoeren.\n\nEen streepje betekent dat dat recht ontbreekt. Bij een directory betekent x dat je erin mag gaan met cd." },
  { v: "Gegeven:\ndrwxr-xr-x 2 root root 4.0K grub.d\n\nWat is grub.d?", a: "Een directory (d).", o: "Toegangsrechten", examen: true,
    uitleg: "Het eerste teken is d: directory.\nEen - zou een gewoon bestand betekenen, een l een link.\ngrub.d staat in /etc en bevat de scripts waarmee de bootloader GRUB zijn menu opbouwt." },
  { v: "Gegeven:\ndrwxr-xr-x 2 root root 4.0K grub.d\n\nWelke rechten heeft de owner? En de group?", a: "Owner: lezen, schrijven, uitvoeren (rwx). Group: lezen en uitvoeren (r-x).", o: "Toegangsrechten", examen: true,
    uitleg: "Na het file type d volgen drie groepjes van drie:\nrwx = owner: lezen, schrijven en uitvoeren.\nr-x = group: lezen en uitvoeren, niet schrijven.\nr-x = other: lezen en uitvoeren.\nDe owner is root (eerste naam na het getal 2), de group is ook root (tweede naam)." },
  { v: "Gegeven:\n-rw-r----- 1 root shadow 828 Aug 15 gshadow\n\nWelke rechten heeft de group en wie is de group?", a: "Group shadow: enkel lezen.", o: "Toegangsrechten", examen: true,
    uitleg: "- = gewoon bestand.\nrw- = owner (root): lezen en schrijven.\nr-- = group (shadow): enkel lezen.\n--- = other: geen rechten.\nDe eerste naam is de owner (root), de tweede naam is de group (shadow).\ngshadow bevat de versleutelde wachtwoorden van groepen, daarom mag niet iedereen het lezen." },
  { v: "Gegeven:\n-rw-r----- 1 root shadow 828 Aug 15 gshadow\n\nWelke rechten heeft other?", a: "Geen rechten.", o: "Toegangsrechten", examen: true,
    uitleg: "De laatste drie tekens zijn de rechten van other: ---. Drie streepjes: geen lezen, geen schrijven, geen uitvoeren.\nEen gewone gebruiker die niet in de groep shadow zit, kan dit bestand dus niet openen." },
  { v: "Gegeven:\n-rw------- 1 root root 821 Aug 9 gshadow-\n\nWelke rechten heeft de owner? Wie is de owner?", a: "root: lezen en schrijven.", o: "Toegangsrechten", examen: true,
    uitleg: "rw- = owner: lezen en schrijven, niet uitvoeren.\nDe eerste naam na het getal 1 is de owner: root.\nGroup en other hebben geen rechten (------).\ngshadow- (met een streepje achteraan) is de backup van gshadow." },
  { v: "Gegeven:\n-rwxrwxr-x 1 piet project 1735 Mar 13 main.c\n\nWie is owner en wie group owner?", a: "Owner: piet. Group owner: project.", o: "Toegangsrechten", examen: true,
    uitleg: "In ls -l staan na het aantal links twee namen: eerst de owner, dan de group.\npiet = owner, project = group.\nDe rechten: piet rwx, de groep project rwx, other r-x." },
  { v: "Welk getal staat voor r, w en x?", a: "r = 4, w = 2, x = 1.", o: "Toegangsrechten", examen: true,
    uitleg: "Elk recht heeft een vaste waarde: r = 4, w = 2, x = 1. Geen recht = 0.\nPer groep (user, group, other) tel je de waarden op. Zo krijg je per groep een getal van 0 tot 7.\nVoorbeeld: rw- = 4 + 2 + 0 = 6." },
  { v: "Welk getal geeft rwx? r-x? r--? rw-? --x? ---?", a: "rwx = 7, r-x = 5, r-- = 4, rw- = 6, --x = 1, --- = 0.", o: "Toegangsrechten", examen: true,
    uitleg: "rwx = 4 + 2 + 1 = 7\nr-x = 4 + 0 + 1 = 5\nr-- = 4 + 0 + 0 = 4\nrw- = 4 + 2 + 0 = 6\n--x = 0 + 0 + 1 = 1\n--- = 0" },
  { v: "Geef met de cijfermethode het commando voor file.txt (in de working directory): user rwx, group enkel uitvoeren, other enkel lezen.", a: "chmod 714 file.txt\n\n(sudo chmod 714 file.txt als het bestand niet van jou is)", o: "Toegangsrechten", examen: true,
    uitleg: "Per groep tel je de waarden op: r = 4, w = 2, x = 1.\nuser rwx: 4 + 2 + 1 = 7\ngroup --x: 1\nother r--: 4\n\nDe volgorde is altijd user, group, other. Op het examen moet het commando gecopy-past kunnen worden en effectief werken: let op de spatie tussen chmod, het getal en de bestandsnaam." },
  { v: "Geef het commando om -rwxr-xr-x te maken van bestand (cijfermethode).", a: "chmod 755 bestand", o: "Toegangsrechten", examen: true,
    uitleg: "Het eerste teken - is het file type, dat verandert chmod niet.\nrwx = 7 (user)\nr-x = 5 (group)\nr-x = 5 (other)\nDus chmod 755 bestand. Dat is de klassieke instelling voor scripts en programma's." },
  { v: "Geef twee manieren om tekst.txt de rechten -rwxr-xr-- te geven.", a: "chmod 754 tekst.txt   of   chmod u=rwx,g=rx,o=r tekst.txt", o: "Toegangsrechten", examen: true,
    uitleg: "Cijfermethode: rwx = 7, r-x = 5, r-- = 4, dus chmod 754 tekst.txt.\nLettermethode: u=rwx (user), g=rx (group), o=r (other), gescheiden door komma's zonder spaties: chmod u=rwx,g=rx,o=r tekst.txt.\nMet = zet je de rechten precies zo, met + en - voeg je toe of neem je af." },
  { v: "Wat doet chmod u-w,g+w,o+w bestandsnaam?", a: "Neemt schrijfrecht af van de owner, geeft schrijfrecht aan group en other.", o: "Toegangsrechten", examen: true,
    uitleg: "u-w: neem het schrijfrecht (w) af van de user (owner).\ng+w: geef het schrijfrecht aan de group.\no+w: geef het schrijfrecht aan other.\nDe andere rechten blijven zoals ze waren. De delen worden gescheiden door komma's, zonder spaties." },
  { v: "Geef de rechten in letters bij chmod 640.", a: "rw-r-----", o: "Toegangsrechten", examen: true,
    uitleg: "6 = 4 + 2 = rw- (user)\n4 = r-- (group)\n0 = --- (other)\nSamen: rw-r-----" },
  { v: "Geef de rechten in letters bij chmod 700.", a: "rwx------", o: "Toegangsrechten", examen: true,
    uitleg: "7 = 4 + 2 + 1 = rwx (user)\n0 = --- (group)\n0 = --- (other)\nSamen: rwx------. Enkel de eigenaar heeft rechten." },
  { v: "Geef het commando dat iedereen (u, g, o) uitvoerrecht geeft op script.sh, met de lettermethode.", a: "chmod a+x script.sh (of chmod ugo+x script.sh)", o: "Toegangsrechten", examen: true,
    uitleg: "a = all: user, group en other samen. +x voegt het uitvoerrecht toe, de andere rechten blijven ongewijzigd.\nchmod ugo+x script.sh doet hetzelfde. chmod +x script.sh werkt meestal ook.\nDaarna kan je het script starten met ./script.sh." },
  { v: "Waarom komen 4, 2 en 1 overeen met r, w en x?", a: "Het zijn de binaire waarden van de posities (100, 010, 001); je telt ze per groep op.", o: "Toegangsrechten", examen: true,
    uitleg: "Elk recht is één bit in een getal van drie bits:\nr = 100 binair = 4\nw = 010 binair = 2\nx = 001 binair = 1\nrwx = 111 binair = 7. Daarom kan elke combinatie als één cijfer van 0 tot 7 geschreven worden." },
];

